// Generated by tests/compile_multiple_choice.py; immutable question IDs and revision.
window.L4_TEST_DATA={"revision":"2026-11-12-tests-1","kind":"derived-learning-tests","sourceSha256":"42c561ed4ec882a2df19061eb325c070157dc28e79ba99ca5e47c0bfa46f4680","tests":[{"id":"T01","title":"Responsible data use","description":"Legislation, organisational rules, classification, ethics and everyday security.","questions":[{"id":"T01-Q01","ksb":"K1","prompt":"Which statements belong in a complete explanation of how data protection law affects an analyst’s work?","options":[{"text":"A permitted system login does not authorise every possible use of personal data.","why":"Access permission and purpose of use are separate checks.","correct":true,"id":"A"},{"text":"Lawfulness, fairness and transparency belong together in the first GDPR principle.","why":"The complete first principle includes all three.","correct":true,"id":"B"},{"text":"Access, analysis, sharing and retention must follow applicable controls and accountability requirements.","why":"Legal obligations affect the whole workflow.","correct":true,"id":"C"},{"text":"Accountability means deleting the record of analytical decisions.","why":"Accountability requires being able to demonstrate compliance.","correct":false,"id":"D"},{"text":"UK GDPR operates alongside the UK Data Protection Act 2018.","why":"Both form the guide’s UK legal context.","correct":true,"id":"E"},{"text":"Removing a name always removes all data protection obligations.","why":"Other fields or linked information may still identify people.","correct":false,"id":"F"},{"text":"Consent is the only possible lawful basis for processing personal data.","why":"The guide explains that consent is one possible basis.","correct":false,"id":"G"},{"text":"Data protection law applies only when a report is published.","why":"Collection, access, use and retention also matter.","correct":false,"id":"H"}],"answer":"UK GDPR operates alongside the UK Data Protection Act 2018. A permitted system login does not authorise every possible use of personal data. Lawfulness, fairness and transparency belong together in the first GDPR principle. Access, analysis, sharing and retention must follow applicable controls and accountability requirements.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."}},{"id":"T01-Q02","ksb":"K2","prompt":"Which elements would make an answer about organisational data rules specific and credible?","options":[{"text":"List policies from another employer as if they were your own.","why":"Organisational claims must reflect your actual workplace.","correct":false,"id":"A"},{"text":"Use any storage location provided the filename is anonymous.","why":"Approved storage and safe content both matter.","correct":false,"id":"B"},{"text":"Explain relevant AI restrictions and consequences of non-compliance.","why":"Tool permissions and practical consequences are part of the guide.","correct":true,"id":"C"},{"text":"Name the policies actually used, their owner or version, and how updates are found.","why":"This grounds the answer in real organisational practice.","correct":true,"id":"D"},{"text":"Connect daily handling decisions to approved storage, sharing and incident procedures.","why":"The answer should show how rules affect your role.","correct":true,"id":"E"},{"text":"Treat a procedure and a standard as identical concepts.","why":"A procedure describes steps; a standard sets a required level or format.","correct":false,"id":"F"},{"text":"Wait for an annual review before reporting a current security concern.","why":"Follow the organisation’s incident route when a concern arises.","correct":false,"id":"G"},{"text":"Assume a free AI website is approved because it accepts uploads.","why":"Availability does not establish organisational permission.","correct":false,"id":"H"}],"answer":"Name the policies actually used, their owner or version, and how updates are found. Connect daily handling decisions to approved storage, sharing and incident procedures. Explain relevant AI restrictions and consequences of non-compliance.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."}},{"id":"T01-Q03","ksb":"K4","prompt":"Which descriptions correctly distinguish the four data types discussed in K4?","options":[{"text":"Research data is collected or produced for research and may remain restricted.","why":"Research purpose does not guarantee public access.","correct":true,"id":"A"},{"text":"Open data permits reuse under an open licence and its conditions.","why":"Reuse rights are central to open data.","correct":true,"id":"B"},{"text":"Public accessibility alone does not establish unrestricted reuse rights.","why":"Public and openly licensed are different properties.","correct":true,"id":"C"},{"text":"Administrative data originates from operations or service delivery.","why":"Its origin distinguishes administrative data.","correct":true,"id":"D"},{"text":"Open, public, administrative and research data are mutually exclusive security markings.","why":"These categories can overlap and are not security markings.","correct":false,"id":"E"},{"text":"Any publicly visible dataset can be redistributed without checking a licence.","why":"Access and reuse rights must both be checked.","correct":false,"id":"F"},{"text":"Administrative data cannot produce an open aggregate release.","why":"The guide explicitly allows that overlap.","correct":false,"id":"G"},{"text":"Research data must always be unstructured.","why":"Research can produce structured or unstructured material.","correct":false,"id":"H"}],"answer":"Open data permits reuse under an open licence and its conditions. Public accessibility alone does not establish unrestricted reuse rights. Administrative data originates from operations or service delivery. Research data is collected or produced for research and may remain restricted.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."}},{"id":"T01-Q04","ksb":"K15","prompt":"An analysis uses online service feedback. Which elements belong in its ethical explanation?","options":[{"text":"Assume people without online feedback have no service concerns.","why":"Absence from the sample is not absence of experience.","correct":false,"id":"A"},{"text":"Remove all context so no one can question the method.","why":"Useful transparency includes methods and limitations.","correct":false,"id":"B"},{"text":"Describe the source, collection method, population and people excluded from the sample.","why":"Ethical assessment starts with how the data arose.","correct":true,"id":"C"},{"text":"Limit decisions that the available feedback and denominators cannot support.","why":"Comment counts alone do not establish representative satisfaction.","correct":true,"id":"D"},{"text":"Explain methods and limitations and identify responsibility for decisions or challenge.","why":"Transparency and accountability support responsible use.","correct":true,"id":"E"},{"text":"Consider whether digital exclusion makes some groups less visible.","why":"Missing groups can create unfair conclusions.","correct":true,"id":"F"},{"text":"Treat legal permission as proof that every possible use is fair.","why":"Ethics also considers appropriateness and harm.","correct":false,"id":"G"},{"text":"Interpret the largest complaint count as the lowest satisfaction rate without a denominator.","why":"Counts and rates answer different questions.","correct":false,"id":"H"}],"answer":"Describe the source, collection method, population and people excluded from the sample. Consider whether digital exclusion makes some groups less visible. Explain methods and limitations and identify responsibility for decisions or challenge. Limit decisions that the available feedback and denominators cannot support.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."}},{"id":"T01-Q05","ksb":"S1","prompt":"Which actions demonstrate Privacy by Design across a real analytical workflow?","options":[{"text":"Agree the purpose, minimum necessary fields and authorised users during planning.","why":"Privacy controls should shape the design from the start.","correct":true,"id":"A"},{"text":"Assume membership of the project team grants unrestricted access.","why":"Actual access approval and least privilege still apply.","correct":false,"id":"B"},{"text":"Keep all working extracts indefinitely to make future work easier.","why":"Storage limitation and organisational retention still matter.","correct":false,"id":"C"},{"text":"Use approved transfers, protected working copies and output disclosure checks.","why":"Controls need to operate throughout the workflow.","correct":true,"id":"D"},{"text":"Apply retention arrangements and review privacy risks when scope changes.","why":"Privacy responsibilities continue after initial access.","correct":true,"id":"E"},{"text":"Add a password only after the final dashboard is complete.","why":"Late protection alone is not Privacy by Design.","correct":false,"id":"F"},{"text":"Treat pseudonymised records as automatically anonymous.","why":"Re-identification may remain possible.","correct":false,"id":"G"},{"text":"Download every available identifier in case it becomes useful.","why":"Data minimisation requires a justified need.","correct":false,"id":"H"}],"answer":"Agree the purpose, minimum necessary fields and authorised users during planning. Use approved transfers, protected working copies and output disclosure checks. Apply retention arrangements and review privacy risks when scope changes.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."}},{"id":"T01-Q06","ksb":"S3","prompt":"Which statements would support a reasoned classification and handling decision?","options":[{"text":"Use low, medium and high as mandatory government labels in every organisation.","why":"The guide does not treat them as universal labels.","correct":false,"id":"A"},{"text":"Treat a classification change as permission to share with anyone.","why":"Access and disclosure controls still apply.","correct":false,"id":"B"},{"text":"Publish all free-text comments once names have been removed.","why":"Context and rare details can still identify people.","correct":false,"id":"C"},{"text":"Assess sensitivity, identifiability, purpose and potential harm using the organisation’s actual scheme.","why":"Classification must reflect context and real rules.","correct":true,"id":"D"},{"text":"Classify a dataset only by whether it is stored in Excel.","why":"Storage format alone does not establish sensitivity.","correct":false,"id":"E"},{"text":"Assume a numeric identifier cannot identify a person.","why":"Numbers may still link to identifiable records.","correct":false,"id":"F"},{"text":"Link the classification to field restrictions, access controls or other justified treatments.","why":"A label should lead to appropriate handling.","correct":true,"id":"G"},{"text":"Explain who authorised an appropriate change in treatment and what risks remained.","why":"Changes require reasoning, authority and checks.","correct":true,"id":"H"}],"answer":"Assess sensitivity, identifiability, purpose and potential harm using the organisation’s actual scheme. Link the classification to field restrictions, access controls or other justified treatments. Explain who authorised an appropriate change in treatment and what risks remained.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."}},{"id":"T01-Q07","ksb":"B1","prompt":"Before a remote stakeholder meeting, which habits demonstrate safe and productive working?","options":[{"text":"Use the agreed reporting route when a permission or incident is unclear.","why":"Seeking appropriate help protects people and work.","correct":true,"id":"A"},{"text":"Check recipients and permissions before sharing a sanitised output.","why":"Safe sharing requires both suitable content and access.","correct":true,"id":"B"},{"text":"Lock an unattended screen and consider what screen sharing exposes.","why":"Security applies beyond the saved report.","correct":true,"id":"C"},{"text":"Broaden permissions personally whenever access slows a meeting.","why":"Unclear permissions require the authorised route.","correct":false,"id":"D"},{"text":"Share an account so colleagues can avoid their own access process.","why":"Shared credentials weaken access control and accountability.","correct":false,"id":"E"},{"text":"Use approved accounts and devices and protect authentication.","why":"Everyday access controls support a secure environment.","correct":true,"id":"F"},{"text":"Move a report to a personal drive to bypass sharing restrictions.","why":"Approved channels and storage remain required.","correct":false,"id":"G"},{"text":"Display unnecessary identifiers because participants are colleagues.","why":"Minimisation and access requirements still apply internally.","correct":false,"id":"H"}],"answer":"Use approved accounts and devices and protect authentication. Check recipients and permissions before sharing a sanitised output. Lock an unattended screen and consider what screen sharing exposes. Use the agreed reporting route when a permission or incident is unclear.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."}},{"id":"T01-Q08","ksb":"K1","prompt":"Which groups of practices correctly apply the GDPR principles beyond obtaining initial access?","options":[{"text":"Reuse records for any convenient purpose once collected.","why":"Proposed reuse needs assessment.","correct":false,"id":"A"},{"text":"Erase the audit trail to achieve data minimisation.","why":"Necessary accountability records require an appropriate retention decision.","correct":false,"id":"B"},{"text":"Protect against unauthorised access or loss and retain evidence of compliance.","why":"This connects integrity/confidentiality and accountability.","correct":true,"id":"C"},{"text":"Check personal information and follow justified retention or deletion arrangements.","why":"This connects accuracy and storage limitation.","correct":true,"id":"D"},{"text":"Define and assess intended reuse, and take only the detail necessary for that purpose.","why":"This connects purpose limitation and data minimisation.","correct":true,"id":"E"},{"text":"Retain personal information forever because the original use was lawful.","why":"A lawful original use does not remove storage limitation.","correct":false,"id":"F"},{"text":"Publish the access credentials to demonstrate transparency.","why":"Transparency does not mean exposing security credentials.","correct":false,"id":"G"},{"text":"Replace uncertain personal facts with invented plausible values.","why":"Accuracy requires appropriate checking, not fabrication.","correct":false,"id":"H"}],"answer":"Define and assess intended reuse, and take only the detail necessary for that purpose. Check personal information and follow justified retention or deletion arrangements. Protect against unauthorised access or loss and retain evidence of compliance.","source":{"anchor":"ksb-k1","guideSha256":"b262fef2ac197676e44e06d72fc42701f85e6be6372be760e44ee986458eada5","excerpt":"Data protection legislation sets the rules for using information about identifiable people."}},{"id":"T01-Q09","ksb":"S3","prompt":"A team wants to publish feedback counts instead of raw comments. Which checks belong in the answer?","options":[{"text":"Record the classification decision, authority and remaining disclosure risks.","why":"The practical decision and its limits need to be visible.","correct":true,"id":"A"},{"text":"Ignore rare categories because only totals are being shown.","why":"Rare categories can increase identification risk.","correct":false,"id":"B"},{"text":"Change the label without checking organisational rules.","why":"The actual classification process must be followed.","correct":false,"id":"C"},{"text":"Use public data as the security label for all resulting counts.","why":"Data type and handling classification are separate.","correct":false,"id":"D"},{"text":"Keep a separately controlled lookup and describe the data as definitely anonymous.","why":"A re-identification key indicates pseudonymisation, not guaranteed anonymity.","correct":false,"id":"E"},{"text":"Count each comment and assume anonymity is guaranteed.","why":"Small or unique groups can still disclose information.","correct":false,"id":"F"},{"text":"Explain why aggregation suits the purpose and apply the approved handling rules.","why":"The treatment must be justified in context.","correct":true,"id":"G"},{"text":"Check small groups, rare events and possible linkage before calling the output anonymous.","why":"Aggregation does not automatically prevent identification.","correct":true,"id":"H"}],"answer":"Check small groups, rare events and possible linkage before calling the output anonymous. Explain why aggregation suits the purpose and apply the approved handling rules. Record the classification decision, authority and remaining disclosure risks.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."}},{"id":"T01-Q10","ksb":"K15","prompt":"Which statements correctly connect consent, transparency and accountability in ethical data use?","options":[{"text":"A framework replaces the need to understand how this dataset was collected.","why":"Ethical reasoning must address the actual data and context.","correct":false,"id":"A"},{"text":"Explain methods, exclusions and limitations to support informed interpretation.","why":"Transparency includes how conclusions were reached.","correct":true,"id":"B"},{"text":"Transparency requires disclosing identifiable raw records to everyone.","why":"Methods can be explained without exposing personal information.","correct":false,"id":"C"},{"text":"Only the analyst who runs the code can bear responsibility for a decision.","why":"Accountability should identify the relevant decision roles.","correct":false,"id":"D"},{"text":"Consent makes every later use ethically acceptable.","why":"Purpose, fairness and harm still need assessment.","correct":false,"id":"E"},{"text":"Consider consent where relevant without assuming it is always the legal basis.","why":"Participation arrangements and lawful basis are not interchangeable.","correct":true,"id":"F"},{"text":"If analysis is lawful, bias no longer needs investigation.","why":"Legal permission does not eliminate ethical responsibilities.","correct":false,"id":"G"},{"text":"Identify responsible roles and a route to question potentially harmful decisions.","why":"Accountability requires responsibility and challenge.","correct":true,"id":"H"}],"answer":"Consider consent where relevant without assuming it is always the legal basis. Explain methods, exclusions and limitations to support informed interpretation. Identify responsible roles and a route to question potentially harmful decisions.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."}}]},{"id":"T02","title":"Planning and delivery","description":"Lifecycle stages, customer needs, collaboration and changes to the work.","questions":[{"id":"T02-Q01","ksb":"K3","prompt":"Which statements collectively explain the data analysis lifecycle rather than just naming tools?","options":[{"text":"Analysis and refining involve methods, validation, comparison and justified revision.","why":"Producing a calculation is not the final analytical check.","correct":true,"id":"A"},{"text":"Communication begins only after all stakeholder decisions are fixed.","why":"Requirements and feedback also require earlier communication.","correct":false,"id":"B"},{"text":"Planning defines the question, stakeholders, scope, success criteria and risks.","why":"The lifecycle starts with the decision need.","correct":true,"id":"C"},{"text":"Communication and implementation explain findings and limitations and support handover and use.","why":"The lifecycle connects analysis to a useful outcome.","correct":true,"id":"D"},{"text":"The lifecycle must never return to a previous stage.","why":"Analysis can iterate when checks or feedback reveal a problem.","correct":false,"id":"E"},{"text":"Data preparation removes the need to validate the final output.","why":"Transformations and results still need checking.","correct":false,"id":"F"},{"text":"Preparation obtains authorised data and profiles, cleans and combines it.","why":"Preparation creates a suitable analytical input.","correct":true,"id":"G"},{"text":"A predictive model is compulsory in every source AM1 project.","why":"The supplied guide allows substantial analysis without a model.","correct":false,"id":"H"}],"answer":"Planning defines the question, stakeholders, scope, success criteria and risks. Preparation obtains authorised data and profiles, cleans and combines it. Analysis and refining involve methods, validation, comparison and justified revision. Communication and implementation explain findings and limitations and support handover and use.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."}},{"id":"T02-Q02","ksb":"S2","prompt":"Which evidence would demonstrate applying the lifecycle in one genuine project?","options":[{"text":"An analysis result with no connection to the original requirement.","why":"The project needs a continuous decision-to-output chain.","correct":false,"id":"A"},{"text":"A generic lifecycle diagram with no account of your actions.","why":"Naming stages alone does not demonstrate application.","correct":false,"id":"B"},{"text":"A list of software installed on the laptop.","why":"Tool availability is not evidence of using the lifecycle.","correct":false,"id":"C"},{"text":"An audience-appropriate output, limitations and a handover or review arrangement.","why":"This completes the chain into communication and use.","correct":true,"id":"D"},{"text":"A copied model answer presented as personal project experience.","why":"Applied evidence must describe genuine work.","correct":false,"id":"E"},{"text":"An agreed question, scope, timetable and risk record from planning.","why":"This demonstrates planning in practice.","correct":true,"id":"F"},{"text":"The methods used, result checks and refinements made in response to evidence.","why":"This demonstrates analysis and refining in practice.","correct":true,"id":"G"},{"text":"A record of authorised acquisition, profiling and transformations.","why":"This demonstrates preparation in practice.","correct":true,"id":"H"}],"answer":"An agreed question, scope, timetable and risk record from planning. A record of authorised acquisition, profiling and transformations. The methods used, result checks and refinements made in response to evidence. An audience-appropriate output, limitations and a handover or review arrangement.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."}},{"id":"T02-Q03","ksb":"K9","prompt":"A stakeholder asks for “a performance dashboard”. Which steps turn this into useful requirements?","options":[{"text":"Choose the chart first and ask about the decision after publication.","why":"The decision should shape the output.","correct":false,"id":"A"},{"text":"Treat the loudest stakeholder as the only affected user.","why":"Affected groups and decision roles should be considered.","correct":false,"id":"B"},{"text":"Keep acceptance criteria implicit so delivery remains flexible.","why":"Agreed criteria make success assessable.","correct":false,"id":"C"},{"text":"Assume the word performance has one universal definition.","why":"Domain definitions must be agreed.","correct":false,"id":"D"},{"text":"Use interviews, workshops or prototypes and confirm an agreed brief.","why":"Elicitation and confirmation reduce misunderstandings.","correct":true,"id":"E"},{"text":"Promise every requested feature without checking time or data access.","why":"Requirements need realistic constraints and priorities.","correct":false,"id":"F"},{"text":"Clarify the decision, users, definitions, constraints and what success means.","why":"A chart request is not yet a complete requirement.","correct":true,"id":"G"},{"text":"Record measurable acceptance criteria, scope, priorities and a route for changes.","why":"Requirements need to guide delivery and assessment of the result.","correct":true,"id":"H"}],"answer":"Clarify the decision, users, definitions, constraints and what success means. Use interviews, workshops or prototypes and confirm an agreed brief. Record measurable acceptance criteria, scope, priorities and a route for changes.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."}},{"id":"T02-Q04","ksb":"S7","prompt":"A manager needs a weekly waiting-time view. Which evidence shows the requirement shaped delivery?","options":[{"text":"Connect refresh and filter needs to the preparation, model and output design.","why":"Requirements should influence the method and deliverable.","correct":true,"id":"A"},{"text":"Translate waiting time into agreed start/end events, units and data-cutoff rules.","why":"The requirement must become an analytical definition.","correct":true,"id":"B"},{"text":"Call the requirement met because the file opens.","why":"Technical availability alone is insufficient acceptance evidence.","correct":false,"id":"C"},{"text":"Exclude all open cases without explaining their treatment.","why":"Population and status rules must be explicit.","correct":false,"id":"D"},{"text":"Use calendar and working days interchangeably.","why":"Different units can change the interpretation.","correct":false,"id":"E"},{"text":"Build the most complex available model regardless of the weekly decision.","why":"Method choice should fit the requirement.","correct":false,"id":"F"},{"text":"Change the scope silently when the first data extract is difficult.","why":"Scope changes need agreement and communication.","correct":false,"id":"G"},{"text":"Validate the output against agreed acceptance checks with the stakeholder.","why":"Delivery needs to be checked against the original need.","correct":true,"id":"H"}],"answer":"Translate waiting time into agreed start/end events, units and data-cutoff rules. Connect refresh and filter needs to the preparation, model and output design. Validate the output against agreed acceptance checks with the stakeholder.","source":{"anchor":"ksb-s7","guideSha256":"762c5d5a314f38868448a38aed918ae5c309770463d456b02ece5c88cba6bd1f","excerpt":"Show a chain from a stated need to planned method, output and acceptance check."}},{"id":"T02-Q05","ksb":"K7","prompt":"Which statements connect UX and domain context to useful analytics?","options":[{"text":"Domain knowledge replaces the need to validate data.","why":"Context and data checks are complementary.","correct":false,"id":"A"},{"text":"UX applies only to public-facing mobile applications.","why":"Internal dashboards and data handovers also have users.","correct":false,"id":"B"},{"text":"More controls always mean a better user experience.","why":"Unnecessary choices can obstruct the task.","correct":false,"id":"C"},{"text":"Calendar days and working days can be substituted without discussion.","why":"That changes the domain meaning of waiting time.","correct":false,"id":"D"},{"text":"Simplicity, clarity and accessibility should guide design and checking.","why":"The guide names these as core principles.","correct":true,"id":"E"},{"text":"Domain rules determine meaningful measures, definitions and exceptions.","why":"A plausible calculation can be misleading in the wrong context.","correct":true,"id":"F"},{"text":"UX concerns whether a person can understand and use an output to complete a task.","why":"UX is about practical use, not appearance alone.","correct":true,"id":"G"},{"text":"A familiar colour palette makes a dashboard accessible by itself.","why":"Other access needs and checks remain necessary.","correct":false,"id":"H"}],"answer":"UX concerns whether a person can understand and use an output to complete a task. Domain rules determine meaningful measures, definitions and exceptions. Simplicity, clarity and accessibility should guide design and checking.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."}},{"id":"T02-Q06","ksb":"S12","prompt":"Which evidence would show communication adapted to two distinct stakeholders?","options":[{"text":"Contrast a decision-focused manager briefing with a technical validation discussion, where these reflect actual work.","why":"Different audiences may need different explanations.","correct":true,"id":"A"},{"text":"Explain feedback received and how collaboration affected the output or decision.","why":"The account needs an observable effect, not just messages sent.","correct":true,"id":"B"},{"text":"Remove all limitations from a non-technical presentation.","why":"Decision-makers still need material caveats.","correct":false,"id":"C"},{"text":"Describe only what the team did without your contribution.","why":"Your own communication and collaboration need to be clear.","correct":false,"id":"D"},{"text":"List suggested stakeholder roles as if you actually worked with them.","why":"Examples are not evidence of personal experience.","correct":false,"id":"E"},{"text":"Send the same technical slide deck unchanged to everyone.","why":"That does not demonstrate adaptation.","correct":false,"id":"F"},{"text":"Describe each stakeholder’s different need and choose a suitable channel and level of detail.","why":"Audience needs should shape communication.","correct":true,"id":"G"},{"text":"Count two emails to the same person as two distinct stakeholders.","why":"The source guide requests a contrast between stakeholders.","correct":false,"id":"H"}],"answer":"Describe each stakeholder’s different need and choose a suitable channel and level of detail. Contrast a decision-focused manager briefing with a technical validation discussion, where these reflect actual work. Explain feedback received and how collaboration affected the output or decision.","source":{"anchor":"ksb-s12","guideSha256":"3eb2f4c5da12f2a05c97da6f15657d048685f3b46342a8ed73abb499f2680160","excerpt":"Show communication with at least two distinct stakeholders as requested in the supplied preparation guide, and cover all relevant stakeholders for the work."}},{"id":"T02-Q07","ksb":"B3","prompt":"Which statements build a strong account of independent and collaborative working?","options":[{"text":"Describe how your contribution affected others, supported by genuine observations or feedback.","why":"Impact on colleagues is part of the behaviour.","correct":true,"id":"A"},{"text":"Use “we” throughout without distinguishing your actions.","why":"That obscures personal responsibility.","correct":false,"id":"B"},{"text":"Identify your own responsibilities, decisions and organised work.","why":"Independence should be visible in the account.","correct":true,"id":"C"},{"text":"Explain when another person’s expertise or a dependency required collaboration.","why":"Working independently does not mean avoiding support.","correct":true,"id":"D"},{"text":"Attribute the whole team’s output to yourself.","why":"Team contributions should be acknowledged accurately.","correct":false,"id":"E"},{"text":"Assume collaboration means waiting for detailed instructions on every step.","why":"Independent initiative and collaboration can coexist.","correct":false,"id":"F"},{"text":"Avoid asking for guidance even outside your authority.","why":"Appropriate support can be necessary.","correct":false,"id":"G"},{"text":"Invent positive feedback because the outcome appears useful.","why":"Claims about impact need real support.","correct":false,"id":"H"}],"answer":"Identify your own responsibilities, decisions and organised work. Explain when another person’s expertise or a dependency required collaboration. Describe how your contribution affected others, supported by genuine observations or feedback.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."}},{"id":"T02-Q08","ksb":"B4","prompt":"A total has risen unexpectedly. Which reasoning would show a logical investigation?","options":[{"text":"Describe every mouse click without explaining why it mattered.","why":"A sequence of actions needs analytical rationale.","correct":false,"id":"A"},{"text":"Stop once the chart looks plausible.","why":"Plausibility alone is not validation.","correct":false,"id":"B"},{"text":"State plausible explanations and test whether the change already exists in the source.","why":"Start by locating the problem rather than guessing.","correct":true,"id":"C"},{"text":"Choose an explanation because a colleague says it often happens.","why":"Experience can suggest a hypothesis but does not prove it.","correct":false,"id":"D"},{"text":"Check extraction counts and join cardinality in a reasoned sequence.","why":"Each check should narrow the possible cause.","correct":true,"id":"E"},{"text":"Remove enough rows to reproduce last week’s total.","why":"A desired total is not evidence for deletion.","correct":false,"id":"F"},{"text":"Revise the conclusion from evidence and explain assumptions and alternatives.","why":"Logical thinking makes the reasoning visible.","correct":true,"id":"G"},{"text":"Change several transformations at once and keep whichever total looks familiar.","why":"That makes the effect of each change unclear.","correct":false,"id":"H"}],"answer":"State plausible explanations and test whether the change already exists in the source. Check extraction counts and join cardinality in a reasoned sequence. Revise the conclusion from evidence and explain assumptions and alternatives.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."}},{"id":"T02-Q09","ksb":"B2","prompt":"An extract unexpectedly lacks a field used in a filter. Which response demonstrates appropriate adaptability?","options":[{"text":"Bypass access controls to obtain a richer extract.","why":"Resourcefulness does not justify bypassing controls.","correct":false,"id":"A"},{"text":"Adjust the preparation within your responsibility and validate the revised result.","why":"Adaptation should preserve quality.","correct":true,"id":"B"},{"text":"Communicate the effect or escalate if the essential requirement cannot be met.","why":"Productive adjustment keeps stakeholders informed.","correct":true,"id":"C"},{"text":"Check whether an authorised alternative exists and whether its meaning is suitable.","why":"A substitute needs permission and semantic checks.","correct":true,"id":"D"},{"text":"Hide the change because the output still looks correct.","why":"Material changes need communication.","correct":false,"id":"E"},{"text":"Invent plausible values so the deadline is unaffected.","why":"Fabrication does not maintain quality.","correct":false,"id":"F"},{"text":"Use a similarly named field without checking its meaning.","why":"Names alone do not establish equivalence.","correct":false,"id":"G"},{"text":"Describe the obstacle only, without explaining your adjustment.","why":"The behaviour requires a response, not merely a problem statement.","correct":false,"id":"H"}],"answer":"Check whether an authorised alternative exists and whether its meaning is suitable. Adjust the preparation within your responsibility and validate the revised result. Communicate the effect or escalate if the essential requirement cannot be met.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."}},{"id":"T02-Q10","ksb":"B7","prompt":"A project shifts from an annual review to an urgent operational briefing. What belongs in the flexibility account?","options":[{"text":"Keep the old plan unchanged to demonstrate consistency.","why":"A materially different context may require a different approach.","correct":false,"id":"A"},{"text":"Claim all original requirements were met after quietly removing half of them.","why":"Changes and exclusions need to be agreed and reported.","correct":false,"id":"B"},{"text":"Drop validation because the revised task is urgent.","why":"The scope can change while essential quality controls remain.","correct":false,"id":"C"},{"text":"Record excluded work, revised risks and remaining limitations.","why":"Trade-offs should remain visible.","correct":true,"id":"D"},{"text":"Agree the minimum defensible scope and revise methods, outputs and dates.","why":"The plan must adapt to the new decision.","correct":true,"id":"E"},{"text":"Compare the original scope and priorities with the changed context.","why":"The broader shift needs to be explicit.","correct":true,"id":"F"},{"text":"Manage stakeholder feedback and explain your personal changes and the outcome.","why":"Flexibility includes expectations and reflection.","correct":true,"id":"G"},{"text":"Describe only a missing spreadsheet column with no broader contextual shift.","why":"That more directly illustrates a small B2 operational obstacle.","correct":false,"id":"H"}],"answer":"Compare the original scope and priorities with the changed context. Agree the minimum defensible scope and revise methods, outputs and dates. Record excluded work, revised risks and remaining limitations. Manage stakeholder feedback and explain your personal changes and the outcome.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."}}]},{"id":"T03","title":"Structures and architecture","description":"Schemas, keys, data sources, infrastructure and defensible tool choices.","questions":[{"id":"T03-Q01","ksb":"K5","prompt":"Which statements would correctly explain the structure of a request table with comments and a nested JSON contact export?","options":[{"text":"The request table has defined fields and types that support consistent querying.","why":"That is a structured schema.","correct":true,"id":"A"},{"text":"The comment field can contain unstructured meaning even inside a table.","why":"A tabular container does not structure the text’s meaning.","correct":true,"id":"B"},{"text":"Images and audio always share the schema of a relational table.","why":"They do not inherently have that analytical tabular structure.","correct":false,"id":"C"},{"text":"Every JSON document is entirely unstructured.","why":"JSON has explicit organisation and can be semi-structured.","correct":false,"id":"D"},{"text":"Putting comments into Excel makes their meaning fully structured.","why":"The container does not remove the need for interpretation.","correct":false,"id":"E"},{"text":"Unstructured content cannot be analysed.","why":"Coding, extraction or review can support analysis.","correct":false,"id":"F"},{"text":"Nested JSON is often semi-structured and may need flattening or aggregation.","why":"Named fields need not form one flat table.","correct":true,"id":"G"},{"text":"A structured table cannot contain any free text.","why":"Structured records can include text fields.","correct":false,"id":"H"}],"answer":"The request table has defined fields and types that support consistent querying. The comment field can contain unstructured meaning even inside a table. Nested JSON is often semi-structured and may need flattening or aggregation.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."}},{"id":"T03-Q02","ksb":"K6","prompt":"Which definitions belong in an accurate explanation of database system design?","options":[{"text":"ETL means load first and transform afterwards.","why":"That order describes ELT; ETL transforms before loading.","correct":false,"id":"A"},{"text":"A database organises data for managed storage, retrieval and updates.","why":"This describes its core role.","correct":true,"id":"B"},{"text":"A warehouse integrates analytical data, often including history from several systems.","why":"A warehouse supports analysis across sources.","correct":true,"id":"C"},{"text":"Every analytical design must be fully normalised to the same degree.","why":"Analytical designs can deliberately denormalise.","correct":false,"id":"D"},{"text":"Normalisation reduces avoidable relational duplication and update anomalies.","why":"That is its purpose, even when analytical designs later denormalise.","correct":true,"id":"E"},{"text":"NoSQL describes one universal table design.","why":"It includes several non-relational approaches.","correct":false,"id":"F"},{"text":"A lake stores varied raw or processed formats but still needs governance and metadata.","why":"Flexible storage does not remove management needs.","correct":true,"id":"G"},{"text":"A data lake automatically guarantees clean data.","why":"Quality controls remain necessary.","correct":false,"id":"H"}],"answer":"A database organises data for managed storage, retrieval and updates. A warehouse integrates analytical data, often including history from several systems. A lake stores varied raw or processed formats but still needs governance and metadata. Normalisation reduces avoidable relational duplication and update anomalies.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."}},{"id":"T03-Q03","ksb":"K10","prompt":"Which statements correctly define keys before combining sources?","options":[{"text":"NULL keys can always be treated as a shared identifier.","why":"Unknown values do not establish a legitimate match.","correct":false,"id":"A"},{"text":"A foreign key is always unique within the referencing table.","why":"Many records may refer to the same related entity.","correct":false,"id":"B"},{"text":"A primary key is whichever column appears first in an export.","why":"Column order does not define a key.","correct":false,"id":"C"},{"text":"Matching column names prove that the relationship is one-to-one.","why":"Grain, values and cardinality must be checked.","correct":false,"id":"D"},{"text":"A composite key uses more than one field, with grain defined before a join.","why":"Multiple fields may jointly identify the intended row.","correct":true,"id":"E"},{"text":"A foreign key refers to a key in a related table.","why":"It represents a relationship between records.","correct":true,"id":"F"},{"text":"A composite key must contain exactly three fields.","why":"It means more than one field, not exactly three.","correct":false,"id":"G"},{"text":"A primary key uniquely identifies a row and cannot be NULL.","why":"Uniqueness and non-null identity are fundamental.","correct":true,"id":"H"}],"answer":"A primary key uniquely identifies a row and cannot be NULL. A foreign key refers to a key in a related table. A composite key uses more than one field, with grain defined before a join.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."}},{"id":"T03-Q04","ksb":"K12","prompt":"Which elements make an architecture explanation specific to the organisation?","options":[{"text":"Describe Azure as the name of every database involved.","why":"A platform label does not identify the actual service or component.","correct":false,"id":"A"},{"text":"Explain how approved storage, retention, connectors and identities constrain analysis.","why":"Policies and infrastructure influence analytical choices.","correct":true,"id":"B"},{"text":"Treat architecture as a list of dashboard colours.","why":"Architecture concerns data systems, flows and governance.","correct":false,"id":"C"},{"text":"Claim Big Data technology is necessary for every modest dataset.","why":"A relational solution can be appropriate at modest scale.","correct":false,"id":"D"},{"text":"Identify ownership, permissions, refresh arrangements and lineage at relevant stages.","why":"These shape how the architecture operates.","correct":true,"id":"E"},{"text":"Include a data lake in the diagram even when the organisation does not use one.","why":"The diagram must reflect actual infrastructure.","correct":false,"id":"F"},{"text":"Assume central storage allows unrestricted local copies.","why":"Storage and access policies still apply.","correct":false,"id":"G"},{"text":"Describe the actual flow from operational sources through transformation to authorised consumption.","why":"Architecture connects components and use.","correct":true,"id":"H"}],"answer":"Describe the actual flow from operational sources through transformation to authorised consumption. Identify ownership, permissions, refresh arrangements and lineage at relevant stages. Explain how approved storage, retention, connectors and identities constrain analysis.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."}},{"id":"T03-Q05","ksb":"S4","prompt":"One request row can have three contacts in a nested export. Which approach accounts for structural differences?","options":[{"text":"Delete all repeated request IDs without investigating their contacts.","why":"Repeated IDs may represent legitimate child records.","correct":false,"id":"A"},{"text":"Choose flattening or aggregation based on whether the analysis needs requests or contacts.","why":"The analytical unit should guide the representation.","correct":true,"id":"B"},{"text":"State the shape, fields, keys and grain of each extracted dataset.","why":"Structural context determines a safe transformation.","correct":true,"id":"C"},{"text":"Ignore row and column counts because both files open successfully.","why":"Shape is useful evidence of structural changes.","correct":false,"id":"D"},{"text":"Reconcile request counts after combining data so repeated contacts do not inflate totals.","why":"A structural adaptation needs validation.","correct":true,"id":"E"},{"text":"Assume every relational source is incapable of storing JSON.","why":"Some relational systems support JSON values.","correct":false,"id":"F"},{"text":"Treat each expanded contact row as a new request.","why":"That changes the unit and inflates request counts.","correct":false,"id":"G"},{"text":"Use the same aggregation regardless of the intended unit.","why":"Methods need to fit the grain.","correct":false,"id":"H"}],"answer":"State the shape, fields, keys and grain of each extracted dataset. Choose flattening or aggregation based on whether the analysis needs requests or contacts. Reconcile request counts after combining data so repeated contacts do not inflate totals.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."}},{"id":"T03-Q06","ksb":"S8","prompt":"Which actions demonstrate a robust left join from requests to a service lookup?","options":[{"text":"Ignore unit and period differences because the keys match.","why":"Matching keys do not guarantee compatible meanings.","correct":false,"id":"A"},{"text":"Define the keys and grain and investigate missing or duplicate lookup keys before joining.","why":"Preparation should establish the intended relationship.","correct":true,"id":"B"},{"text":"Replace missing service keys with an arbitrary valid service ID.","why":"That invents a relationship.","correct":false,"id":"C"},{"text":"Assume a left join can never increase the row count.","why":"Repeated right-side keys can multiply rows.","correct":false,"id":"D"},{"text":"Resolve conflicting lookup values through an authoritative rule before relying on them.","why":"An arbitrary row choice is not a defensible correction.","correct":true,"id":"E"},{"text":"Treat a basic lookup formula as a full account of all combination risks.","why":"The guide requires a reasoned, validated process.","correct":false,"id":"F"},{"text":"Use the first lookup value returned and assume it is authoritative.","why":"Return order does not prove the correct value.","correct":false,"id":"G"},{"text":"Check row counts, unmatched keys and relevant totals after the join.","why":"A completed join still needs validation.","correct":true,"id":"H"}],"answer":"Define the keys and grain and investigate missing or duplicate lookup keys before joining. Resolve conflicting lookup values through an authoritative rule before relying on them. Check row counts, unmatched keys and relevant totals after the join.","source":{"anchor":"ksb-s8","guideSha256":"0f5cddb86161986b79351977142757eead70691fc156a7d038e573f11ffcd428","excerpt":"Demonstrate a repeatable join in an appropriate tool, with explicit keys, grain and validation."}},{"id":"T03-Q07","ksb":"S9","prompt":"Which explanation appropriately connects an analysis tool to organisational infrastructure?","options":[{"text":"Give Azure alone as the complete description of a storage service.","why":"Name the relevant service where appropriate and safe.","correct":false,"id":"A"},{"text":"Assume BI connections do not need access controls.","why":"Governed reporting still needs authorised access.","correct":false,"id":"B"},{"text":"Justify the fit and distinguish querying data from administering infrastructure.","why":"The account must reflect your actual role.","correct":true,"id":"C"},{"text":"Claim database administration because you ran a SELECT query.","why":"Querying does not establish administration responsibility.","correct":false,"id":"D"},{"text":"Choose a tool without checking the systems it must connect to.","why":"Infrastructure fit is part of the choice.","correct":false,"id":"E"},{"text":"Use an unsupported connector to avoid approved access limits.","why":"Compatibility and authorisation remain required.","correct":false,"id":"F"},{"text":"Name the actual tool, connector or query environment and the component accessed.","why":"A specific connection is more useful than a platform list.","correct":true,"id":"G"},{"text":"Describe approved authentication, least privilege and any gateway or refresh constraints.","why":"Access and infrastructure constraints matter.","correct":true,"id":"H"}],"answer":"Name the actual tool, connector or query environment and the component accessed. Describe approved authentication, least privilege and any gateway or refresh constraints. Justify the fit and distinguish querying data from administering infrastructure.","source":{"anchor":"ksb-s9","guideSha256":"71edb943dfa86f21da3b61052db03a37b8a51cb0ecbfb3ae823aafcd6a641aa9","excerpt":"Explain which tool you used to interact with which architectural component and why the connection satisfied the organisation's constraints."}},{"id":"T03-Q08","ksb":"K11","prompt":"Which comparisons would justify organisational analytical tools rather than simply name favourites?","options":[{"text":"Include approved use, licensing, accessibility, skills and maintenance.","why":"Practical constraints affect the outcome.","correct":true,"id":"A"},{"text":"Explain the trade-offs between supported licensed tools and flexible custom code.","why":"Neither route is universally superior.","correct":true,"id":"B"},{"text":"Choose Python because code is always cheaper to maintain.","why":"Code still needs testing, support and suitable deployment.","correct":false,"id":"C"},{"text":"Assume all tools mentioned in the guide are approved by your employer.","why":"Actual availability and permission vary.","correct":false,"id":"D"},{"text":"Choose a licensed tool because a licence guarantees accessible outputs.","why":"Accessibility still depends on design and use.","correct":false,"id":"E"},{"text":"Compare capability, scale, source connectivity and reproducibility against the requirement.","why":"Tools should fit the analytical task.","correct":true,"id":"F"},{"text":"Treat popularity as proof of the best project outcome.","why":"The justification must address the particular requirement.","correct":false,"id":"G"},{"text":"Evaluate only the initial purchase cost.","why":"Ongoing support and delivery constraints also matter.","correct":false,"id":"H"}],"answer":"Compare capability, scale, source connectivity and reproducibility against the requirement. Include approved use, licensing, accessibility, skills and maintenance. Explain the trade-offs between supported licensed tools and flexible custom code.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."}},{"id":"T03-Q09","ksb":"S15","prompt":"Which account demonstrates selecting and applying an appropriate analysis tool?","options":[{"text":"Set decision criteria from the requirement and organisational environment.","why":"A reasoned choice needs relevant criteria.","correct":true,"id":"A"},{"text":"Assume a single tool must handle every stage.","why":"A justified approved combination may be best.","correct":false,"id":"B"},{"text":"Describe an unused alternative as though you implemented it.","why":"The account must distinguish evaluation from performed work.","correct":false,"id":"C"},{"text":"Say only that the tool was familiar.","why":"Familiarity is relevant but insufficient alone.","correct":false,"id":"D"},{"text":"Ignore ownership because the analysis has already been delivered.","why":"Future support affects suitability.","correct":false,"id":"E"},{"text":"Compare realistically available options and explain the trade-offs.","why":"Hypothetical unavailable tools do not establish the practical choice.","correct":true,"id":"F"},{"text":"Show how the selected tool was used and evaluate the resulting outcome.","why":"Selection and actual application both matter.","correct":true,"id":"G"},{"text":"Select the most complex method regardless of the question.","why":"Complexity is not a measure of suitability.","correct":false,"id":"H"}],"answer":"Set decision criteria from the requirement and organisational environment. Compare realistically available options and explain the trade-offs. Show how the selected tool was used and evaluate the resulting outcome.","source":{"anchor":"ksb-s15","guideSha256":"57328e157ecc1d18b4913049441798285a61136023fe24c5a86de23aca366ccb","excerpt":"Show the decision process and then show that you applied the selected tool."}},{"id":"T03-Q10","ksb":"K4","prompt":"A waiting-time project combines operational requests with published population aggregates. Which reasoning is sound?","options":[{"text":"Check the published aggregates’ licence, geography, dates and definitions before reuse.","why":"Public access does not establish suitability or unrestricted rights.","correct":true,"id":"A"},{"text":"The operational requests become research data merely because an analyst opens them.","why":"Using operational records for analysis does not alone change their origin.","correct":false,"id":"B"},{"text":"The requests are administrative because they arise from service delivery.","why":"Classification considers origin and purpose.","correct":true,"id":"C"},{"text":"Open data always contains personal identifiers.","why":"Open describes reuse conditions, not an obligatory content type.","correct":false,"id":"D"},{"text":"Any public population total is a suitable denominator for any period.","why":"Time and population alignment matter.","correct":false,"id":"E"},{"text":"Explain why other data types were unnecessary, unsuitable or unavailable for this project.","why":"The guide asks for reasoned use and non-use.","correct":true,"id":"F"},{"text":"Using two sources proves that every possible data type was used.","why":"Source count does not establish data-type coverage.","correct":false,"id":"G"},{"text":"The four data types replace the need for sensitivity assessment.","why":"Handling classification remains a separate decision.","correct":false,"id":"H"}],"answer":"The requests are administrative because they arise from service delivery. Check the published aggregates’ licence, geography, dates and definitions before reuse. Explain why other data types were unnecessary, unsuitable or unavailable for this project.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."}}]},{"id":"T04","title":"Quality and integration","description":"Find quality risks, reason about joins and validate corrections.","questions":[{"id":"T04-Q01","ksb":"K8","prompt":"Which distinctions belong in an accurate data-quality explanation?","options":[{"text":"Accuracy concerns whether a value correctly represents reality; validity concerns allowed format, type or range.","why":"A valid format does not prove a true value.","correct":true,"id":"A"},{"text":"A valid date string proves that the event happened on that date.","why":"Format compliance does not establish accuracy.","correct":false,"id":"B"},{"text":"Uniqueness means no field value may ever repeat.","why":"Many legitimate fields contain repeated values.","correct":false,"id":"C"},{"text":"Consistency and timeliness concern agreement of meanings and suitability of currency or availability.","why":"Quality is related to the decision being supported.","correct":true,"id":"D"},{"text":"Completeness concerns expected records and required fields.","why":"A dataset can be complete but inaccurate.","correct":true,"id":"E"},{"text":"Uniqueness must be assessed at the intended grain.","why":"Legitimate child records should not be mistaken for duplicate entities.","correct":true,"id":"F"},{"text":"Completeness means all values are factually correct.","why":"That confuses completeness with accuracy.","correct":false,"id":"G"},{"text":"Timeliness is only the time taken to draw the chart.","why":"It concerns whether suitable data is available when needed.","correct":false,"id":"H"}],"answer":"Accuracy concerns whether a value correctly represents reality; validity concerns allowed format, type or range. Completeness concerns expected records and required fields. Uniqueness must be assessed at the intended grain. Consistency and timeliness concern agreement of meanings and suitability of currency or availability.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."}},{"id":"T04-Q02","ksb":"S6","prompt":"Which sequence demonstrates resolving a quality problem during analysis?","options":[{"text":"Replace every NULL with zero without checking its meaning.","why":"NULL and zero are not generally interchangeable.","correct":false,"id":"A"},{"text":"Report success without checking the resulting output.","why":"A correction can introduce new errors.","correct":false,"id":"B"},{"text":"Profile data and measure the issue and its effect on the intended decision.","why":"Treatment should respond to an understood risk.","correct":true,"id":"C"},{"text":"Investigate the cause and use a justified correction or approved escalation.","why":"Changes should be reasoned and within authority.","correct":true,"id":"D"},{"text":"Change source-system values without authority to save time.","why":"Follow the approved correction route.","correct":false,"id":"E"},{"text":"Delete every unusual row before exploring its cause.","why":"Unusual values may be genuine.","correct":false,"id":"F"},{"text":"Keep the problem from stakeholders who depend on the output.","why":"Material risks and delays need appropriate communication.","correct":false,"id":"G"},{"text":"Validate the corrected result and document the treatment and remaining limitations.","why":"Resolution needs checks and a usable record.","correct":true,"id":"H"}],"answer":"Profile data and measure the issue and its effect on the intended decision. Investigate the cause and use a justified correction or approved escalation. Validate the corrected result and document the treatment and remaining limitations.","source":{"anchor":"ksb-s6","guideSha256":"dc73f26172b8e4a54be65d1401e4ce48334bb00e7eafdface7d2f4064df7d492","excerpt":"Demonstrate a complete issue-handling loop: detect, measure, assess impact, investigate, mitigate or escalate, resolve where authorised, and validate."}},{"id":"T04-Q03","ksb":"S8","prompt":"A left join turns 100 request rows into 120 rows. Five requests have no service match. Which responses are justified?","options":[{"text":"Drop duplicates on all columns without identifying the authoritative lookup value.","why":"Conflicting values require a defensible rule.","correct":false,"id":"A"},{"text":"Divide every reported count by 1.2 to force the old total.","why":"A blanket factor does not fix record relationships.","correct":false,"id":"B"},{"text":"Call the output complete because the query ran without an error.","why":"Execution success does not prove analytical correctness.","correct":false,"id":"C"},{"text":"Switch to an inner join solely to hide unmatched records.","why":"Exclusion changes the population and needs justification.","correct":false,"id":"D"},{"text":"Identify and explain unmatched requests instead of silently losing them.","why":"A left join can preserve records while exposing missing matches.","correct":true,"id":"E"},{"text":"Assume the extra 20 rows represent newly discovered requests.","why":"A join can multiply existing rows.","correct":false,"id":"F"},{"text":"Reconcile totals again after an authorised correction and document remaining limitations.","why":"An apparently corrected join still needs validation.","correct":true,"id":"G"},{"text":"Investigate duplicate right-side keys and the intended join cardinality.","why":"The lookup may be multiplying request rows.","correct":true,"id":"H"}],"answer":"Investigate duplicate right-side keys and the intended join cardinality. Identify and explain unmatched requests instead of silently losing them. Reconcile totals again after an authorised correction and document remaining limitations.","source":{"anchor":"ksb-s8","guideSha256":"0f5cddb86161986b79351977142757eead70691fc156a7d038e573f11ffcd428","excerpt":"Demonstrate a repeatable join in an appropriate tool, with explicit keys, grain and validation."}},{"id":"T04-Q04","ksb":"K10","prompt":"Which statements accurately distinguish joins, UNION and UNION ALL?","options":[{"text":"UNION matches primary keys to foreign keys across columns.","why":"That describes a relationship-based combination, not appending rows.","correct":false,"id":"A"},{"text":"UNION ALL appends compatible result rows while retaining duplicates.","why":"Duplicate handling distinguishes it from UNION.","correct":true,"id":"B"},{"text":"An inner join preserves every unmatched row from both sides.","why":"That is not inner-join behaviour.","correct":false,"id":"C"},{"text":"A full outer join discards unmatched values.","why":"It includes unmatched rows from both sides.","correct":false,"id":"D"},{"text":"UNION appends compatible result rows and removes duplicates.","why":"It is a set operation, not a join type.","correct":true,"id":"E"},{"text":"UNION ALL automatically cleans duplicate business entities.","why":"It retains duplicate result rows.","correct":false,"id":"F"},{"text":"Joins combine related row combinations using a condition and may change cardinality.","why":"Join semantics depend on matching relationships.","correct":true,"id":"G"},{"text":"Compatible column counts alone guarantee identical business definitions.","why":"Units, types and meanings also need checking.","correct":false,"id":"H"}],"answer":"Joins combine related row combinations using a condition and may change cardinality. UNION appends compatible result rows and removes duplicates. UNION ALL appends compatible result rows while retaining duplicates.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."}},{"id":"T04-Q05","ksb":"S4","prompt":"A request export and a service-month summary have different grains. Which choices preserve analytical meaning?","options":[{"text":"Check that duplicated summary values are not summed repeatedly after joining.","why":"A repeated aggregate can inflate a result.","correct":true,"id":"A"},{"text":"Choose transformations solely because they use fewer clicks.","why":"Structural correctness and validation matter.","correct":false,"id":"B"},{"text":"Align the required aggregation and keys before combining the records.","why":"The join should fit the intended unit of analysis.","correct":true,"id":"C"},{"text":"Describe one row per request versus one row per service per month.","why":"Explicit grain exposes the structural difference.","correct":true,"id":"D"},{"text":"Ignore the extraction date when reporting shape.","why":"Counts should refer to a defined extract.","correct":false,"id":"E"},{"text":"Assume a shared service column makes the tables interchangeable.","why":"Their units of observation remain different.","correct":false,"id":"F"},{"text":"Count each service-month row as an individual request.","why":"That confuses summary and record-level data.","correct":false,"id":"G"},{"text":"Repeat the monthly total for each request and sum it to obtain demand.","why":"This multiplies the aggregate.","correct":false,"id":"H"}],"answer":"Describe one row per request versus one row per service per month. Align the required aggregation and keys before combining the records. Check that duplicated summary values are not summed repeatedly after joining.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."}},{"id":"T04-Q06","ksb":"B5","prompt":"A report count is inflated because duplicate lookup keys were loaded. Which account distinguishes the root cause?","options":[{"text":"Correct the current data and introduce an authorised validation gate with an owner and later monitoring.","why":"Prevention addresses recurrence rather than only the symptom.","correct":true,"id":"A"},{"text":"Remove random requests until the total matches expectations.","why":"That hides the symptom and damages the dataset.","correct":false,"id":"B"},{"text":"Treat the inflated count as the symptom and the join multiplication as the immediate mechanism.","why":"Different levels of explanation should be separated.","correct":true,"id":"C"},{"text":"Call the chart the root cause because it displays the wrong number.","why":"The display may only expose an upstream issue.","correct":false,"id":"D"},{"text":"Fix today’s lookup and guarantee the issue can never recur.","why":"Prevention and monitoring are needed, and guarantees are unwarranted.","correct":false,"id":"E"},{"text":"Treat a Five Whys diagram alone as proof of causation.","why":"A method organises hypotheses but does not prove them.","correct":false,"id":"F"},{"text":"Choose the first plausible explanation without checking the load process.","why":"Competing explanations require evidence.","correct":false,"id":"G"},{"text":"Investigate why duplicate keys entered the lookup and test that explanation with evidence.","why":"The underlying process cause needs investigation.","correct":true,"id":"H"}],"answer":"Treat the inflated count as the symptom and the join multiplication as the immediate mechanism. Investigate why duplicate keys entered the lookup and test that explanation with evidence. Correct the current data and introduce an authorised validation gate with an owner and later monitoring.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."}},{"id":"T04-Q07","ksb":"B4","prompt":"Which actions make an analytical investigation logical and independently reasoned?","options":[{"text":"Equate a more complicated workflow with a more logical one.","why":"Complexity does not establish sound reasoning.","correct":false,"id":"A"},{"text":"Change several unrelated steps at once to maximise the chance of improvement.","why":"The effects become hard to attribute.","correct":false,"id":"B"},{"text":"Ignore evidence that contradicts the preferred explanation.","why":"Contrary evidence should inform revision.","correct":false,"id":"C"},{"text":"Repeat instructions without explaining analytical choices.","why":"B4 needs visible logical reasoning.","correct":false,"id":"D"},{"text":"Compare evidence before and after a suspected transformation.","why":"Controlled comparisons can locate an effect.","correct":true,"id":"E"},{"text":"Use the expected answer as the only validation check.","why":"Independent checks need evidence beyond expectation.","correct":false,"id":"F"},{"text":"State assumptions and order checks so each result narrows the problem.","why":"A justified sequence makes the reasoning assessable.","correct":true,"id":"G"},{"text":"Distinguish a supported conclusion from a plausible explanation and evaluate alternatives.","why":"Evidence should drive judgement.","correct":true,"id":"H"}],"answer":"State assumptions and order checks so each result narrows the problem. Compare evidence before and after a suspected transformation. Distinguish a supported conclusion from a plausible explanation and evaluate alternatives.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."}},{"id":"T04-Q08","ksb":"S6","prompt":"Quality profiling finds no material issues in an extract. Which account is honest and useful?","options":[{"text":"Say checking was unnecessary because no issue was visible.","why":"The finding should follow appropriate checks.","correct":false,"id":"A"},{"text":"Describe a possible escalation as one you actually performed.","why":"Hypothetical and actual actions must remain distinct.","correct":false,"id":"B"},{"text":"Explain limitations and why the data was suitable for the intended analysis.","why":"Checks do not establish unlimited fitness for every use.","correct":true,"id":"C"},{"text":"Mark every dimension perfect without explaining measures or rules.","why":"A conclusion needs evidence and context.","correct":false,"id":"D"},{"text":"Distinguish any hypothetical escalation route from actions actually taken.","why":"Do not fabricate a quality incident.","correct":true,"id":"E"},{"text":"Invent a resolved data defect to make the portfolio more convincing.","why":"Work examples must be genuine.","correct":false,"id":"F"},{"text":"Describe the actual rules checked, results and coverage of the checks.","why":"A clean result still needs evidence of checking.","correct":true,"id":"G"},{"text":"Claim no quality risks can ever exist because this extract passed.","why":"Checks have a scope and limitations.","correct":false,"id":"H"}],"answer":"Describe the actual rules checked, results and coverage of the checks. Explain limitations and why the data was suitable for the intended analysis. Distinguish any hypothetical escalation route from actions actually taken.","source":{"anchor":"ksb-s6","guideSha256":"dc73f26172b8e4a54be65d1401e4ce48334bb00e7eafdface7d2f4064df7d492","excerpt":"Demonstrate a complete issue-handling loop: detect, measure, assess impact, investigate, mitigate or escalate, resolve where authorised, and validate."}},{"id":"T04-Q09","ksb":"S3","prompt":"A qualitative comment contains rare personal circumstances. Which treatment is reasoned?","options":[{"text":"Replace the name with an ID and treat all risk as removed.","why":"Pseudonymisation may leave identification possible.","correct":false,"id":"A"},{"text":"Use an approved redaction or thematic aggregate suited to the purpose.","why":"Treatment should preserve useful meaning while controlling risk.","correct":true,"id":"B"},{"text":"Let the charting tool decide the organisation’s handling rules.","why":"Classification requires organisational policy and judgement.","correct":false,"id":"C"},{"text":"Explain the classification, approval and remaining disclosure checks.","why":"The handling decision should be accountable.","correct":true,"id":"D"},{"text":"Use the open-data label because the report is intended for publication.","why":"Intended audience does not establish a safe classification.","correct":false,"id":"E"},{"text":"Publish the quote because qualitative data is not personal data.","why":"Free text can identify people.","correct":false,"id":"F"},{"text":"Assume converting the quote to a count always anonymises it.","why":"Rare or small groups may remain identifiable.","correct":false,"id":"G"},{"text":"Assess identification risk from the comment and from linkage or small groups.","why":"Names are not the only identifying information.","correct":true,"id":"H"}],"answer":"Assess identification risk from the comment and from linkage or small groups. Use an approved redaction or thematic aggregate suited to the purpose. Explain the classification, approval and remaining disclosure checks.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."}},{"id":"T04-Q10","ksb":"K8","prompt":"Which interpretation of NULLs and outliers supports trustworthy analysis?","options":[{"text":"Replace all missing durations with zero because zero is numeric.","why":"That can distort the distribution and meaning.","correct":false,"id":"A"},{"text":"Investigate whether NULL means unknown, not applicable or not yet recorded.","why":"The meaning determines appropriate treatment.","correct":true,"id":"B"},{"text":"Assess how any exclusion or imputation changes the result and document the choice.","why":"Treatment can affect conclusions and uncertainty.","correct":true,"id":"C"},{"text":"Delete every point outside a visual cluster.","why":"Extreme observations may be valid.","correct":false,"id":"D"},{"text":"Assume a missing completion date proves a zero-duration completed case.","why":"It may instead indicate an open case.","correct":false,"id":"E"},{"text":"Treat imputed values as independently observed facts.","why":"Observed and estimated values should be distinguished.","correct":false,"id":"F"},{"text":"Keep all invalid dates because deletion is never allowed.","why":"A justified correction or exclusion can be appropriate.","correct":false,"id":"G"},{"text":"Check an unusual value before deciding whether it is an error or a genuine observation.","why":"Outlier status alone does not establish an error.","correct":true,"id":"H"}],"answer":"Investigate whether NULL means unknown, not applicable or not yet recorded. Check an unusual value before deciding whether it is an error or a genuine observation. Assess how any exclusion or imputation changes the result and document the choice.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."}}]},{"id":"T05","title":"Statistics and interpretation","description":"EDA, summary measures, hypotheses and business interpretation of uncertainty.","questions":[{"id":"T05-Q01","ksb":"K13","prompt":"For a complete descriptive-statistics explanation, which statements are accurate?","options":[{"text":"The median is the middle ordered value and can be useful for skewed data.","why":"Its interpretation depends on ordering rather than magnitude of extremes.","correct":true,"id":"A"},{"text":"Standard deviation is measured in squared units of the original data.","why":"That describes variance’s units.","correct":false,"id":"B"},{"text":"The median is the largest observed value.","why":"It is a central ordered value.","correct":false,"id":"C"},{"text":"A sample variance is always calculated by dividing squared deviations by n.","why":"The guide’s sample estimate commonly uses n minus one.","correct":false,"id":"D"},{"text":"The mode is the most frequent value or category and need not be unique.","why":"More than one value can share the highest frequency.","correct":true,"id":"E"},{"text":"The mean is the sum divided by count and can be sensitive to extreme observations.","why":"Large values can move the mean substantially.","correct":true,"id":"F"},{"text":"Standard deviation is the square root of variance and uses the original measurement units.","why":"Variance instead uses squared units.","correct":true,"id":"G"},{"text":"Every dataset has exactly one mode.","why":"A dataset may have multiple modes or no useful unique mode.","correct":false,"id":"H"}],"answer":"The mean is the sum divided by count and can be sensitive to extreme observations. The median is the middle ordered value and can be useful for skewed data. The mode is the most frequent value or category and need not be unique. Standard deviation is the square root of variance and uses the original measurement units.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."}},{"id":"T05-Q02","ksb":"K13","prompt":"Which statements correctly explain inferential statistical testing?","options":[{"text":"State a null reference claim and an alternative claim about the population or process.","why":"Hypotheses describe what is being tested.","correct":true,"id":"A"},{"text":"Choose the test and assumptions to match the design and data.","why":"A named test is not automatically suitable.","correct":true,"id":"B"},{"text":"Failing to reject the null proves two processes are identical.","why":"Insufficient evidence of a difference is not proof of equality.","correct":false,"id":"C"},{"text":"A p-value is the probability that the null hypothesis is true.","why":"That is not the guide’s definition.","correct":false,"id":"D"},{"text":"Select alpha before looking for a favourable test result.","why":"The threshold should reflect a planned decision rule.","correct":true,"id":"E"},{"text":"Alpha is the size of the observed business improvement.","why":"It is a significance threshold related to Type I error.","correct":false,"id":"F"},{"text":"A statistically significant result proves the effect is operationally important.","why":"Practical significance requires separate interpretation.","correct":false,"id":"G"},{"text":"A p-value is conditional on the null hypothesis and model assumptions.","why":"It concerns outcomes at least as extreme under that model.","correct":true,"id":"H"}],"answer":"State a null reference claim and an alternative claim about the population or process. Select alpha before looking for a favourable test result. A p-value is conditional on the null hypothesis and model assumptions. Choose the test and assumptions to match the design and data.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."}},{"id":"T05-Q03","ksb":"K13","prompt":"Which statements connect Type I/II errors to analytical decisions?","options":[{"text":"A Type I error means the spreadsheet file has an invalid format.","why":"Statistical decision errors are different from file-quality errors.","correct":false,"id":"A"},{"text":"Choose and explain the decision threshold in light of relevant business error consequences.","why":"Different decision errors may have different costs.","correct":true,"id":"B"},{"text":"A Type I error rejects a null hypothesis that is actually true.","why":"It is a false rejection under the test framework.","correct":true,"id":"C"},{"text":"A non-significant result eliminates the risk of a missed effect.","why":"A Type II error can remain possible.","correct":false,"id":"D"},{"text":"A Type II error fails to reject a null hypothesis that is actually false.","why":"It is a missed rejection under the framework.","correct":true,"id":"E"},{"text":"Choosing the smallest p-value after many unreported tests preserves the original error interpretation.","why":"Unreported multiple testing undermines that interpretation.","correct":false,"id":"F"},{"text":"Setting alpha to 0.05 guarantees this particular conclusion is 95% correct.","why":"The threshold is not a probability that a conclusion is true.","correct":false,"id":"G"},{"text":"A Type II error proves that a true null was rejected.","why":"That describes neither the correct Type II definition nor a proof from one result.","correct":false,"id":"H"}],"answer":"A Type I error rejects a null hypothesis that is actually true. A Type II error fails to reject a null hypothesis that is actually false. Choose and explain the decision threshold in light of relevant business error consequences.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."}},{"id":"T05-Q04","ksb":"S10","prompt":"Which steps constitute a defensible start to exploratory data analysis?","options":[{"text":"Use only the mean even when distributions are strongly skewed.","why":"Other summaries may reveal important information.","correct":false,"id":"A"},{"text":"Inspect distributions, outliers and relevant groups.","why":"Patterns and unusual observations need context.","correct":true,"id":"B"},{"text":"Consider collection methods and sampling bias.","why":"The sample may not represent the target population.","correct":true,"id":"C"},{"text":"Assume neat synthetic numbers establish representativeness.","why":"Real collection methods and sampling need assessment.","correct":false,"id":"D"},{"text":"Delete outliers automatically before any investigation.","why":"Outliers may be genuine and informative.","correct":false,"id":"E"},{"text":"Check shape, types, missingness and duplicates.","why":"Basic profiling helps establish what is being analysed.","correct":true,"id":"F"},{"text":"Calculate a p-value before defining the question.","why":"The question and design should guide the analysis.","correct":false,"id":"G"},{"text":"Choose summaries and charts suited to the question and data.","why":"EDA should support the business problem.","correct":true,"id":"H"}],"answer":"Check shape, types, missingness and duplicates. Inspect distributions, outliers and relevant groups. Consider collection methods and sampling bias. Choose summaries and charts suited to the question and data.","source":{"anchor":"ksb-s10","guideSha256":"c42a163b39508febe898efed0feb19bdc5dadb606e898701905c94e865897acc","excerpt":"Start with EDA: check shape, data types, missingness, duplicates, distributions, outliers, groups and possible sampling bias."}},{"id":"T05-Q05","ksb":"S10","prompt":"The guide’s synthetic Welch test gives a mean difference of 2 days, p=0.08052 and alpha=0.05. Which interpretation is sound?","options":[{"text":"Discuss the estimated difference, uncertainty, small samples and practical importance.","why":"Business interpretation needs more than a threshold.","correct":true,"id":"A"},{"text":"The sample difference proves the change was caused by the service process.","why":"The test does not by itself establish causation.","correct":false,"id":"B"},{"text":"The result does not prove that the two population means are equal.","why":"Non-rejection is not evidence of exact equality.","correct":true,"id":"C"},{"text":"Reject the null because 0.08052 is below 0.5.","why":"The stated threshold is 0.05, not 0.5.","correct":false,"id":"D"},{"text":"Do not reject the equal-population-means null at the stated threshold.","why":"The p-value exceeds 0.05.","correct":true,"id":"E"},{"text":"There is an 8.052% probability that the null is true.","why":"That misinterprets the p-value.","correct":false,"id":"F"},{"text":"Five tidy observations per group prove normality and representativeness.","why":"Those assumptions cannot be established from neat numbers alone.","correct":false,"id":"G"},{"text":"Report a guaranteed 2-day improvement for every future case.","why":"The estimated mean difference is uncertain and not an individual guarantee.","correct":false,"id":"H"}],"answer":"Do not reject the equal-population-means null at the stated threshold. The result does not prove that the two population means are equal. Discuss the estimated difference, uncertainty, small samples and practical importance.","source":{"anchor":"ksb-s10","guideSha256":"c42a163b39508febe898efed0feb19bdc5dadb606e898701905c94e865897acc","excerpt":"Start with EDA: check shape, data types, missingness, duplicates, distributions, outliers, groups and possible sampling bias."}},{"id":"T05-Q06","ksb":"S10","prompt":"Which choices correctly connect an inferential method to the design?","options":[{"text":"Distinguish paired measurements from independent groups before choosing a mean-comparison test.","why":"The relationship between observations affects the method.","correct":true,"id":"A"},{"text":"Use an independent-groups test for every before-and-after dataset.","why":"Paired observations may require paired analysis.","correct":false,"id":"B"},{"text":"State hypotheses and interpret the result alongside effect size and uncertainty.","why":"A complete applied explanation includes purpose and interpretation.","correct":true,"id":"C"},{"text":"Treat correlation as proof that one variable causes another.","why":"Association alone does not establish causation.","correct":false,"id":"D"},{"text":"Check relevant distributional, independence and collection assumptions.","why":"A test result depends on more than software execution.","correct":true,"id":"E"},{"text":"Assume the guide requires a t-test in every possible project.","why":"A t-test is one suitable method for some questions.","correct":false,"id":"F"},{"text":"Assume every predictive library reports inferential p-values.","why":"The guide explicitly cautions that they do not all do so.","correct":false,"id":"G"},{"text":"Choose a test only because it produces the desired significance.","why":"Method choice should follow the question and design.","correct":false,"id":"H"}],"answer":"Distinguish paired measurements from independent groups before choosing a mean-comparison test. Check relevant distributional, independence and collection assumptions. State hypotheses and interpret the result alongside effect size and uncertainty.","source":{"anchor":"ksb-s10","guideSha256":"c42a163b39508febe898efed0feb19bdc5dadb606e898701905c94e865897acc","excerpt":"Start with EDA: check shape, data types, missingness, duplicates, distributions, outliers, groups and possible sampling bias."}},{"id":"T05-Q07","ksb":"K8","prompt":"A duration column contains missing completion dates for open cases. Which quality explanation is appropriate?","options":[{"text":"Document how the chosen treatment affects summaries and limitations.","why":"Handling choices can change the interpretation.","correct":true,"id":"A"},{"text":"Backfill a completion date to make every row complete.","why":"Completeness should not be achieved by inventing events.","correct":false,"id":"B"},{"text":"Treat zero and unknown as equivalent values.","why":"Zero is an observed quantity, not a universal missing-value code.","correct":false,"id":"C"},{"text":"Separate completed-case duration from the count or status of open cases.","why":"These measures describe different populations and questions.","correct":true,"id":"D"},{"text":"Assume the entire extract is unusable whenever a NULL appears.","why":"Some missing values have legitimate meanings.","correct":false,"id":"E"},{"text":"Convert each missing completion date into zero elapsed days.","why":"That can falsely represent open cases as immediate completions.","correct":false,"id":"F"},{"text":"Check whether missingness reflects an open case rather than a data-entry failure.","why":"The meaning of NULL matters.","correct":true,"id":"G"},{"text":"Drop open cases from every possible analysis without explanation.","why":"Their treatment depends on the decision and measure.","correct":false,"id":"H"}],"answer":"Check whether missingness reflects an open case rather than a data-entry failure. Separate completed-case duration from the count or status of open cases. Document how the chosen treatment affects summaries and limitations.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."}},{"id":"T05-Q08","ksb":"K3","prompt":"A statistical check exposes a preparation problem. Which lifecycle reasoning is appropriate?","options":[{"text":"Communicate the revised result, limitations and implications for the original decision.","why":"The lifecycle connects checked analysis to use.","correct":true,"id":"A"},{"text":"Keep the first result because the lifecycle permits each stage only once.","why":"The guide explicitly describes iteration.","correct":false,"id":"B"},{"text":"Skip validation after correction because preparation is now complete.","why":"A changed input can affect the result.","correct":false,"id":"C"},{"text":"Re-run analysis and refining checks after changing the input.","why":"The result must be validated again after a change.","correct":true,"id":"D"},{"text":"Hide the problem from the final explanation to keep the story linear.","why":"Material changes and limitations should remain visible.","correct":false,"id":"E"},{"text":"Treat opening statistical software as completion of every lifecycle stage.","why":"Tool use alone does not demonstrate the staged work.","correct":false,"id":"F"},{"text":"Require the same predictive model in every AM1 project.","why":"The guide permits substantial analysis without a model.","correct":false,"id":"G"},{"text":"Return to the relevant preparation step and document a justified correction.","why":"The lifecycle is iterative when validation reveals a problem.","correct":true,"id":"H"}],"answer":"Return to the relevant preparation step and document a justified correction. Re-run analysis and refining checks after changing the input. Communicate the revised result, limitations and implications for the original decision.","source":{"anchor":"ksb-k3","guideSha256":"9e5bea7a65cf2fe496e698c90fa537a3d364b937a260a44abc4d61260f8d84fb","excerpt":"The lifecycle turns a decision need into a useful analytical output: Planning: define the question, stakeholders, scope, success criteria, data needs, risks and timetable."}},{"id":"T05-Q09","ksb":"K14","prompt":"Which examples accurately distinguish descriptive, predictive and prescriptive analytics?","options":[{"text":"Estimating next month’s demand with uncertainty is predictive analysis.","why":"It estimates an unknown or future outcome.","correct":true,"id":"A"},{"text":"A fitted predictive model automatically proves causation.","why":"Predictive association does not establish a causal effect.","correct":false,"id":"B"},{"text":"Summarising historical completed-request waits is descriptive analysis.","why":"It describes observed results.","correct":true,"id":"C"},{"text":"A forecast alone is already a complete staffing recommendation.","why":"Prediction does not by itself choose a justified action.","correct":false,"id":"D"},{"text":"Logistic regression always predicts a numerical duration directly.","why":"It estimates a probability for a defined class in the guide’s example.","correct":false,"id":"E"},{"text":"An unsupported recommendation demonstrates prescriptive analytical benefit.","why":"The action needs evidence, objectives and constraints.","correct":false,"id":"F"},{"text":"Comparing feasible staffing actions against capacity, cost and service needs is prescriptive analysis.","why":"It supports a choice of action under constraints.","correct":true,"id":"G"},{"text":"A chart of last month’s actuals is automatically a future forecast.","why":"Historical description and prediction are distinct.","correct":false,"id":"H"}],"answer":"Summarising historical completed-request waits is descriptive analysis. Estimating next month’s demand with uncertainty is predictive analysis. Comparing feasible staffing actions against capacity, cost and service needs is prescriptive analysis.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."}},{"id":"T05-Q10","ksb":"S14","prompt":"Which choices would communicate both quantitative spread and qualitative feedback responsibly?","options":[{"text":"Use a distribution or other suitable summary to reveal variation in durations.","why":"An average alone can hide spread.","correct":true,"id":"A"},{"text":"Publish rare identifiable comments because they explain an outlier.","why":"Useful context does not override disclosure controls.","correct":false,"id":"B"},{"text":"Replace a skewed distribution with one average and claim all cases are similar.","why":"That hides variation and may mislead.","correct":false,"id":"C"},{"text":"Present the number of comments as a satisfaction percentage without a denominator.","why":"A percentage requires an appropriate base.","correct":false,"id":"D"},{"text":"State denominators and sampling limits when relating themes to numerical results.","why":"Feedback counts are not automatically population satisfaction rates.","correct":true,"id":"E"},{"text":"Treat numeric theme codes as continuous measurements by default.","why":"A code may represent a qualitative category.","correct":false,"id":"F"},{"text":"Assume converting themes to counts removes interpretation and bias.","why":"Coding still involves qualitative judgement.","correct":false,"id":"G"},{"text":"Define thematic categories and explain how comments were coded and checked.","why":"Qualitative interpretation needs a consistent process.","correct":true,"id":"H"}],"answer":"Use a distribution or other suitable summary to reveal variation in durations. Define thematic categories and explain how comments were coded and checked. State denominators and sampling limits when relating themes to numerical results.","source":{"anchor":"ksb-s14","guideSha256":"fe8ae3c33cc1c8e2bd105b901a97f94b26b72e1bf2336b438fdcac2217923fbd","excerpt":"Quantitative data measures quantities such as counts or durations."}}]},{"id":"T06","title":"Prediction and forecasting","description":"Models, validation, uncertainty and the distinction between a prediction and an action.","questions":[{"id":"T06-Q01","ksb":"K14","prompt":"Which chain connects all three analytics types in a service-capacity explanation?","options":[{"text":"Skip descriptive exploration because a predictive library is available.","why":"The data and question still need understanding.","correct":false,"id":"A"},{"text":"Use the words descriptive, predictive and prescriptive without showing their connection.","why":"Naming types does not demonstrate their use.","correct":false,"id":"B"},{"text":"Recommend extra staff solely because a fitted line slopes upwards.","why":"The recommendation needs evidence and constraints.","correct":false,"id":"C"},{"text":"Describe observed demand or waiting-time patterns.","why":"This establishes the descriptive starting point.","correct":true,"id":"D"},{"text":"Assume a prediction establishes why demand changes.","why":"Forecasting does not automatically identify causes.","correct":false,"id":"E"},{"text":"Treat predicted counts as guaranteed future events.","why":"Predictions remain uncertain.","correct":false,"id":"F"},{"text":"Compare feasible responses against capacity and other constraints before recommending an action.","why":"Prescription requires a defensible decision step.","correct":true,"id":"G"},{"text":"Estimate future demand with a justified model and uncertainty.","why":"This adds prediction rather than only historical reporting.","correct":true,"id":"H"}],"answer":"Describe observed demand or waiting-time patterns. Estimate future demand with a justified model and uncertainty. Compare feasible responses against capacity and other constraints before recommending an action.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."}},{"id":"T06-Q02","ksb":"S11","prompt":"Which practices protect a predictive evaluation from leakage?","options":[{"text":"Use features available at the time the prediction would actually be made.","why":"Future information can create misleading performance.","correct":true,"id":"A"},{"text":"Scale the entire dataset before splitting because scaling is not modelling.","why":"Preprocessing can leak evaluation information.","correct":false,"id":"B"},{"text":"Fit preprocessing on training data and evaluate on unseen observations.","why":"Evaluation data should not influence fitting.","correct":true,"id":"C"},{"text":"Choose splits appropriate to time order or entity relationships and compare a baseline.","why":"Validation should reflect the intended use.","correct":true,"id":"D"},{"text":"Include the eventual completion date when predicting delay at case creation.","why":"That feature is unavailable at prediction time.","correct":false,"id":"E"},{"text":"Allow the same entity into train and test without checking dependence.","why":"Entity overlap can make evaluation unrealistic.","correct":false,"id":"F"},{"text":"Tune repeatedly on the final test set and still call it untouched.","why":"Repeated selection uses its information.","correct":false,"id":"G"},{"text":"Judge generalisation only by training error.","why":"Training performance does not measure unseen-data performance.","correct":false,"id":"H"}],"answer":"Use features available at the time the prediction would actually be made. Fit preprocessing on training data and evaluate on unseen observations. Choose splits appropriate to time order or entity relationships and compare a baseline.","source":{"anchor":"ksb-s11","guideSha256":"6cf9f35febad9dfa76eb76a27e7eeb97d5312845c45dea04f5b5a8390f488a54","excerpt":"Demonstrate a connected descriptive, predictive and prescriptive workflow."}},{"id":"T06-Q03","ksb":"S13","prompt":"Which elements belong in a complete forecasting account?","options":[{"text":"Treat a good fit on historical training points as sufficient forecast validation.","why":"Training fit alone is insufficient.","correct":false,"id":"A"},{"text":"Include unknown future actuals in an error metric.","why":"Error requires known observed values.","correct":false,"id":"B"},{"text":"Plot the series and investigate missing periods, trend and seasonality.","why":"The series’ features guide suitable modelling.","correct":true,"id":"C"},{"text":"Randomly mix all future and past rows for every time-series evaluation.","why":"That can break the intended time-order test.","correct":false,"id":"D"},{"text":"Preserve time order and evaluate on later known observations against a baseline.","why":"A forecast needs realistic out-of-sample checking.","correct":true,"id":"E"},{"text":"Claim annual seasonality from any nine consecutive monthly observations.","why":"That history cannot establish annual repetition reliably.","correct":false,"id":"F"},{"text":"Define the target, frequency, history window and future horizon.","why":"The forecast needs a clear outcome and time context.","correct":true,"id":"G"},{"text":"Present a forecast visual, error metrics, projections and limitations.","why":"The account should communicate accuracy and uncertainty.","correct":true,"id":"H"}],"answer":"Define the target, frequency, history window and future horizon. Plot the series and investigate missing periods, trend and seasonality. Preserve time order and evaluate on later known observations against a baseline. Present a forecast visual, error metrics, projections and limitations.","source":{"anchor":"ksb-s13","guideSha256":"46cd9f000fc581e86430af6ad25dc0a9ed1c49d6ecee41240ee5c9cf42272384","excerpt":"Define a forecast target, frequency, observation window and horizon."}},{"id":"T06-Q04","ksb":"S13","prompt":"For the synthetic forecast 113+3t, January 2025 is t=1. Which statements correctly interpret the guide’s worked example?","options":[{"text":"Its holdout RMSE uses actuals 144,149,151 and is about 2.160 requests.","why":"The squared errors are 1,9,4 over the same three months.","correct":true,"id":"A"},{"text":"The frozen model forecasts October–December 2025 as 143, 146 and 149 requests.","why":"Those months correspond to t=10,11,12.","correct":true,"id":"B"},{"text":"Refitting on October–December actuals leaves the original test fully untouched.","why":"Those observations would then influence the fitted model.","correct":false,"id":"C"},{"text":"The three projections prove demand will rise by exactly three every month.","why":"The toy model is not a guarantee about reality.","correct":false,"id":"D"},{"text":"January–March 2026 projections of 152,155,158 are future estimates, not holdout actuals.","why":"They correspond to t=13,14,15 and remain uncertain.","correct":true,"id":"E"},{"text":"The model’s holdout RMSE is exactly zero because the trend is linear.","why":"The held-out actuals differ from the predictions.","correct":false,"id":"F"},{"text":"The better toy RMSE establishes superiority on every future dataset.","why":"The comparison supports only this narrow example and split.","correct":false,"id":"G"},{"text":"Nine training months prove annual seasonality.","why":"They do not establish a repeating annual pattern.","correct":false,"id":"H"}],"answer":"The frozen model forecasts October–December 2025 as 143, 146 and 149 requests. Its holdout RMSE uses actuals 144,149,151 and is about 2.160 requests. January–March 2026 projections of 152,155,158 are future estimates, not holdout actuals.","source":{"anchor":"ksb-s13","guideSha256":"46cd9f000fc581e86430af6ad25dc0a9ed1c49d6ecee41240ee5c9cf42272384","excerpt":"Define a forecast target, frequency, observation window and horizon."}},{"id":"T06-Q05","ksb":"S11","prompt":"Which elements justify a regression model in a practical prediction task?","options":[{"text":"Define the target and unit, using linear regression for a numerical target or logistic regression for a defined binary outcome where suitable.","why":"The method should fit the outcome.","correct":true,"id":"A"},{"text":"Treat a high training score as proof that every subgroup is well served.","why":"Subgroup and unseen-data checks remain necessary.","correct":false,"id":"B"},{"text":"Use logistic regression to guarantee an exact continuous completion duration.","why":"It estimates a class probability in this context.","correct":false,"id":"C"},{"text":"Explain assumptions, limitations and the decision the prediction can inform.","why":"A useful model needs interpretation and responsible use.","correct":true,"id":"D"},{"text":"Compare unseen-data performance with a baseline and examine relevant subgroup behaviour.","why":"One headline metric can conceal important weaknesses.","correct":true,"id":"E"},{"text":"Select features because they are known only after the outcome occurs.","why":"That creates prediction-time leakage.","correct":false,"id":"F"},{"text":"Report only the best metric and suppress model limitations.","why":"Responsible reporting includes material limitations.","correct":false,"id":"G"},{"text":"Assume regression coefficients always represent causal effects.","why":"Causal interpretation needs additional justification.","correct":false,"id":"H"}],"answer":"Define the target and unit, using linear regression for a numerical target or logistic regression for a defined binary outcome where suitable. Compare unseen-data performance with a baseline and examine relevant subgroup behaviour. Explain assumptions, limitations and the decision the prediction can inform.","source":{"anchor":"ksb-s11","guideSha256":"6cf9f35febad9dfa76eb76a27e7eeb97d5312845c45dea04f5b5a8390f488a54","excerpt":"Demonstrate a connected descriptive, predictive and prescriptive workflow."}},{"id":"T06-Q06","ksb":"K13","prompt":"Which statements guard against overclaiming statistical evidence around a predictive model?","options":[{"text":"Every machine-learning library supplies valid inferential p-values automatically.","why":"Inferential output depends on the method and implementation.","correct":false,"id":"A"},{"text":"Alpha is a measure of business profit.","why":"It is a statistical decision threshold.","correct":false,"id":"B"},{"text":"A non-significant result proves the effect is exactly zero.","why":"Non-rejection is not proof of equality.","correct":false,"id":"C"},{"text":"An observed association authorises any intervention on the associated variable.","why":"Intervention decisions need further reasoning and context.","correct":false,"id":"D"},{"text":"Statistical evidence needs effect size, uncertainty and practical interpretation.","why":"A threshold alone is not a business conclusion.","correct":true,"id":"E"},{"text":"A small p-value guarantees accurate predictions on new data.","why":"Predictive accuracy needs suitable evaluation.","correct":false,"id":"F"},{"text":"Correlation or regression does not by itself prove a causal effect.","why":"Prediction and causation are separate claims.","correct":true,"id":"G"},{"text":"A p-value is conditional on a stated null and model assumptions.","why":"It is not the probability that a model or null is true.","correct":true,"id":"H"}],"answer":"A p-value is conditional on a stated null and model assumptions. Statistical evidence needs effect size, uncertainty and practical interpretation. Correlation or regression does not by itself prove a causal effect.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."}},{"id":"T06-Q07","ksb":"B6","prompt":"An initial model performs worse than a baseline. Which response demonstrates resilience and learning?","options":[{"text":"Claim resilience means never finding the work difficult.","why":"The guide focuses on constructive response to difficulty.","correct":false,"id":"A"},{"text":"Invent a successful result because an imperfect outcome cannot count.","why":"Honest setbacks can support meaningful reflection.","correct":false,"id":"B"},{"text":"Accept and report the result honestly while reassessing features, assumptions or leakage.","why":"An unfavourable result can still inform useful work.","correct":true,"id":"C"},{"text":"Seek appropriate support and try a justified alternative without abandoning quality controls.","why":"Resilience includes constructive changes and support.","correct":true,"id":"D"},{"text":"Document a concrete lesson and how it changes later practice.","why":"The behaviour is demonstrated through response and learning.","correct":true,"id":"E"},{"text":"Ignore feedback because independence requires solving everything alone.","why":"Appropriate support is compatible with resilience.","correct":false,"id":"F"},{"text":"Keep tuning until the test score improves and omit the repeated selection.","why":"Unreported test reuse can mislead.","correct":false,"id":"G"},{"text":"Hide the baseline comparison to present the project as successful.","why":"That conceals relevant evidence.","correct":false,"id":"H"}],"answer":"Accept and report the result honestly while reassessing features, assumptions or leakage. Seek appropriate support and try a justified alternative without abandoning quality controls. Document a concrete lesson and how it changes later practice.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."}},{"id":"T06-Q08","ksb":"S13","prompt":"Which statements correctly discuss stationarity and model assumptions?","options":[{"text":"Remove every demand spike to enforce smoothness.","why":"Unusual observations should be investigated before treatment.","correct":false,"id":"A"},{"text":"Investigate the series and choose assumptions and transformations appropriate to the selected model.","why":"Forecast methods differ in what they require.","correct":true,"id":"B"},{"text":"No visible trend alone does not establish stationarity.","why":"Other distributional properties and dependence may change.","correct":true,"id":"C"},{"text":"ARIMA is automatically the best model for every short series.","why":"Choice needs evidence, features and a suitable comparison.","correct":false,"id":"D"},{"text":"An ADF result replaces all judgement about seasonality and business context.","why":"A test does not cover every modelling consideration.","correct":false,"id":"E"},{"text":"Every series without a trend is stationary.","why":"Variance or dependence can still change.","correct":false,"id":"F"},{"text":"An ADF test may be useful where appropriate, but the guide does not make it universal.","why":"Method choice should be justified rather than mechanical.","correct":true,"id":"G"},{"text":"Every forecasting method requires exactly the same stationarity checks.","why":"Requirements depend on the model.","correct":false,"id":"H"}],"answer":"No visible trend alone does not establish stationarity. Investigate the series and choose assumptions and transformations appropriate to the selected model. An ADF test may be useful where appropriate, but the guide does not make it universal.","source":{"anchor":"ksb-s13","guideSha256":"46cd9f000fc581e86430af6ad25dc0a9ed1c49d6ecee41240ee5c9cf42272384","excerpt":"Define a forecast target, frequency, observation window and horizon."}},{"id":"T06-Q09","ksb":"K15","prompt":"Which ethical considerations remain relevant after a predictive model has a good overall metric?","options":[{"text":"Explain methods and limitations and identify accountable decision roles.","why":"Transparent use supports challenge and responsibility.","correct":true,"id":"A"},{"text":"A good average metric proves the model is fair to every group.","why":"Subgroup effects may differ.","correct":false,"id":"B"},{"text":"Treat legal permission as sufficient ethical justification.","why":"Fairness and appropriateness still need consideration.","correct":false,"id":"C"},{"text":"Check whose outcomes are missing or measured differently and who may be harmed.","why":"Overall accuracy can hide bias and exclusions.","correct":true,"id":"D"},{"text":"Remove demographic labels and assume all bias disappears.","why":"Other variables and sampling can preserve bias.","correct":false,"id":"E"},{"text":"Describe an uncertain prediction as an established fact to encourage adoption.","why":"That undermines transparency.","correct":false,"id":"F"},{"text":"Limit recommendations to what the data and purpose can support.","why":"Predictive performance does not justify every use.","correct":true,"id":"G"},{"text":"Ignore data collection once the model has been trained.","why":"Collection and exclusions affect ethical interpretation.","correct":false,"id":"H"}],"answer":"Check whose outcomes are missing or measured differently and who may be harmed. Explain methods and limitations and identify accountable decision roles. Limit recommendations to what the data and purpose can support.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."}},{"id":"T06-Q10","ksb":"S11","prompt":"A model’s training RMSE is 2 days but holdout RMSE is 15; a baseline scores 12 on the same holdout. Which conclusions are justified?","options":[{"text":"Assume the model with more features must be the optimum tool.","why":"Complexity is not a substitute for performance and suitability.","correct":false,"id":"A"},{"text":"The baseline performed better on this held-out RMSE comparison.","why":"Lower RMSE is better on the same outcome and observations.","correct":true,"id":"B"},{"text":"Deploy the complex model because its training error is lowest.","why":"Training error alone does not establish useful generalisation.","correct":false,"id":"C"},{"text":"Remove difficult holdout cases without a justified rule.","why":"That biases the evaluation.","correct":false,"id":"D"},{"text":"Evaluate feasible actions and their risks rather than automatically deploying the more complex model.","why":"A prediction needs a justified decision context.","correct":true,"id":"E"},{"text":"Claim the gap proves leakage was definitely the cause.","why":"Several explanations need investigation.","correct":false,"id":"F"},{"text":"Report 2 days as the validated future prediction error.","why":"That is the training metric, not the holdout result.","correct":false,"id":"G"},{"text":"Investigate overfitting or leakage and report uncertainty and limitations.","why":"The training/holdout gap merits investigation, not a single assumed cause.","correct":true,"id":"H"}],"answer":"The baseline performed better on this held-out RMSE comparison. Investigate overfitting or leakage and report uncertainty and limitations. Evaluate feasible actions and their risks rather than automatically deploying the more complex model.","source":{"anchor":"ksb-s11","guideSha256":"6cf9f35febad9dfa76eb76a27e7eeb97d5312845c45dea04f5b5a8390f488a54","excerpt":"Demonstrate a connected descriptive, predictive and prescriptive workflow."}}]},{"id":"T07","title":"Visuals and communication","description":"Accessible outputs, domain meaning and stakeholder-focused decisions.","questions":[{"id":"T07-Q01","ksb":"K7","prompt":"Which choices connect domain context to the user’s actual dashboard task?","options":[{"text":"Distinguish open cases from the population used for completed-case duration.","why":"Status and population rules affect interpretation.","correct":true,"id":"A"},{"text":"Assume internal users have no accessibility needs.","why":"Accessibility matters for internal users too.","correct":false,"id":"B"},{"text":"Use clear definitions and interactions that help the intended user make the decision.","why":"UX should serve the task.","correct":true,"id":"C"},{"text":"Assume every department uses the same service target.","why":"Domain rules can vary and need checking.","correct":false,"id":"D"},{"text":"Show the largest possible number of controls regardless of the task.","why":"Unnecessary controls can obstruct use.","correct":false,"id":"E"},{"text":"Treat an attractive colour scheme as sufficient domain knowledge.","why":"Appearance does not establish correct definitions.","correct":false,"id":"F"},{"text":"Agree whether waiting time uses calendar or working days.","why":"The unit changes the domain meaning.","correct":true,"id":"G"},{"text":"Use a generic metric without confirming its operational meaning.","why":"A plausible label can conceal a misleading measure.","correct":false,"id":"H"}],"answer":"Agree whether waiting time uses calendar or working days. Distinguish open cases from the population used for completed-case duration. Use clear definitions and interactions that help the intended user make the decision.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."}},{"id":"T07-Q02","ksb":"S5","prompt":"Which design choices would support accessible and useful visual output?","options":[{"text":"Assume every BI tool automatically provides the same keyboard experience.","why":"Capabilities and limitations need checking.","correct":false,"id":"A"},{"text":"Use unlabeled icons as the only explanation of complex measures.","why":"Clear labels help understanding and access.","correct":false,"id":"B"},{"text":"Claim WCAG conformance because accessibility was a design intention.","why":"Conformance requires appropriate evaluation.","correct":false,"id":"C"},{"text":"Use red and green alone to distinguish important categories.","why":"Meaning should not depend only on colour.","correct":false,"id":"D"},{"text":"Place the decision-critical measure and definition prominently and group related information.","why":"Visual hierarchy should support the user’s task.","correct":true,"id":"E"},{"text":"Hide the data cutoff so the layout looks cleaner.","why":"Currency affects interpretation.","correct":false,"id":"F"},{"text":"Make filter state, refresh timing, labels and units visible.","why":"Users need context for interpreting results.","correct":true,"id":"G"},{"text":"Use contrast, non-colour cues, suitable alternatives and relevant interaction checks.","why":"Accessibility needs more than a colour choice.","correct":true,"id":"H"}],"answer":"Place the decision-critical measure and definition prominently and group related information. Make filter state, refresh timing, labels and units visible. Use contrast, non-colour cues, suitable alternatives and relevant interaction checks.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."}},{"id":"T07-Q03","ksb":"S14","prompt":"Which statements accurately represent qualitative and quantitative data?","options":[{"text":"Qualitative information cannot appear in a chart.","why":"Categories and thematic summaries can be visualised.","correct":false,"id":"A"},{"text":"Coding comments into themes needs consistent interpretation and retained context.","why":"Counting themes does not remove the qualitative judgement.","correct":true,"id":"B"},{"text":"Every comment must be assigned exactly one theme in every project.","why":"Multiple themes may be appropriate if explicitly defined.","correct":false,"id":"C"},{"text":"A pie chart automatically establishes representative satisfaction.","why":"Sampling and denominators still matter.","correct":false,"id":"D"},{"text":"Converting comments to counts removes all risk of bias.","why":"Coding and collection can still introduce bias.","correct":false,"id":"E"},{"text":"Durations and counts measure quantitative quantities.","why":"Their numeric values represent amounts.","correct":true,"id":"F"},{"text":"Categories, opinions and experiences are qualitative even when assigned numeric codes.","why":"A code does not automatically become a continuous measure.","correct":true,"id":"G"},{"text":"Any field stored as a number is quantitative.","why":"A numeric category code may remain qualitative.","correct":false,"id":"H"}],"answer":"Durations and counts measure quantitative quantities. Categories, opinions and experiences are qualitative even when assigned numeric codes. Coding comments into themes needs consistent interpretation and retained context.","source":{"anchor":"ksb-s14","guideSha256":"fe8ae3c33cc1c8e2bd105b901a97f94b26b72e1bf2336b438fdcac2217923fbd","excerpt":"Quantitative data measures quantities such as counts or durations."}},{"id":"T07-Q04","ksb":"S12","prompt":"A manager and data engineer need the same findings. Which communication plan demonstrates adaptation?","options":[{"text":"Count repeated messages to the manager as two stakeholders.","why":"Distinct stakeholders are needed for the requested contrast.","correct":false,"id":"A"},{"text":"Give the manager a concise decision, accessible visual, caveats and recommendation.","why":"The briefing should support the operational choice.","correct":true,"id":"B"},{"text":"Remove uncertainty from the manager’s briefing to keep it short.","why":"Material uncertainty still affects the decision.","correct":false,"id":"C"},{"text":"Claim the engineer approved a correction without actual feedback.","why":"Evidence must describe genuine collaboration.","correct":false,"id":"D"},{"text":"Give the engineer relevant grain, key, transformation and validation detail.","why":"Technical collaboration needs suitable diagnostic information.","correct":true,"id":"E"},{"text":"Send raw diagnostic logs to everyone as the only explanation.","why":"Detail should fit the audience and purpose.","correct":false,"id":"F"},{"text":"Explain what each stakeholder contributed and how feedback changed the work.","why":"Communication should include listening and an effect.","correct":true,"id":"G"},{"text":"Use identical channels for every situation regardless of urgency.","why":"Context can change the appropriate channel.","correct":false,"id":"H"}],"answer":"Give the manager a concise decision, accessible visual, caveats and recommendation. Give the engineer relevant grain, key, transformation and validation detail. Explain what each stakeholder contributed and how feedback changed the work.","source":{"anchor":"ksb-s12","guideSha256":"3eb2f4c5da12f2a05c97da6f15657d048685f3b46342a8ed73abb499f2680160","excerpt":"Show communication with at least two distinct stakeholders as requested in the supplied preparation guide, and cover all relevant stakeholders for the work."}},{"id":"T07-Q05","ksb":"K9","prompt":"Which use of a Power-Interest Matrix supports requirements work?","options":[{"text":"Revisit the map and include affected groups who may have little influence.","why":"A static map can overlook important users.","correct":true,"id":"A"},{"text":"Exclude lower-power users because they cannot approve the budget.","why":"They can still be affected and provide essential requirements.","correct":false,"id":"B"},{"text":"Let the highest-power person’s preferred chart define every analytical method.","why":"The business question and constraints also matter.","correct":false,"id":"C"},{"text":"Use the matrix to decide data protection permissions automatically.","why":"Stakeholder mapping does not replace access control.","correct":false,"id":"D"},{"text":"Replace an agreed brief with the matrix alone.","why":"Detailed requirements and acceptance criteria are still needed.","correct":false,"id":"E"},{"text":"Plan close involvement for high-power/high-interest stakeholders and suitable engagement for others.","why":"Engagement should reflect stakeholder needs and influence.","correct":true,"id":"F"},{"text":"Assume stakeholder interests never change during the project.","why":"Engagement needs review as work changes.","correct":false,"id":"G"},{"text":"Identify affected people and decision-makers rather than only requested chart features.","why":"Requirements concern decisions and users.","correct":true,"id":"H"}],"answer":"Identify affected people and decision-makers rather than only requested chart features. Plan close involvement for high-power/high-interest stakeholders and suitable engagement for others. Revisit the map and include affected groups who may have little influence.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."}},{"id":"T07-Q06","ksb":"S7","prompt":"Which traceability chain demonstrates implementing a regular-report requirement?","options":[{"text":"Add unrelated features until the report is too late for the meeting.","why":"Scope should serve the stated decision.","correct":false,"id":"A"},{"text":"Use a visually polished output as the only acceptance check.","why":"Analytical correctness and user needs also matter.","correct":false,"id":"B"},{"text":"Build the defined measures and filters into the planned method and deliverable.","why":"Requirements should shape implementation.","correct":true,"id":"C"},{"text":"Change the cutoff after seeing the result without recording it.","why":"Time definitions must be clear and changes agreed.","correct":false,"id":"D"},{"text":"Check a refresh cycle and reconcile the output against agreed acceptance criteria.","why":"The delivered process needs validation.","correct":true,"id":"E"},{"text":"Treat a successful first refresh as proof the process needs no owner.","why":"Ongoing use requires responsibility and handover.","correct":false,"id":"F"},{"text":"Agree the data cutoff, refresh dependencies and responsible owner.","why":"The regular meeting imposes operational requirements.","correct":true,"id":"G"},{"text":"Assume all stakeholders interpret the same metric label identically.","why":"Definitions need agreement.","correct":false,"id":"H"}],"answer":"Agree the data cutoff, refresh dependencies and responsible owner. Build the defined measures and filters into the planned method and deliverable. Check a refresh cycle and reconcile the output against agreed acceptance criteria.","source":{"anchor":"ksb-s7","guideSha256":"762c5d5a314f38868448a38aed918ae5c309770463d456b02ece5c88cba6bd1f","excerpt":"Show a chain from a stated need to planned method, output and acceptance check."}},{"id":"T07-Q07","ksb":"S15","prompt":"Which tool-selection reasoning would suit a recurring, governed visual report?","options":[{"text":"Choose the newest tool regardless of source compatibility.","why":"Novelty does not establish suitability.","correct":false,"id":"A"},{"text":"Apply a justified approved tool or combination and evaluate its delivered result.","why":"The account should show use as well as selection.","correct":true,"id":"B"},{"text":"Compare available options against connectivity, reproducibility, security and sharing needs.","why":"Selection should reflect the actual requirement.","correct":true,"id":"C"},{"text":"Choose solely on personal familiarity without other criteria.","why":"Familiarity is only one factor.","correct":false,"id":"D"},{"text":"Treat a prototype screenshot as proof the recurring process is maintained.","why":"Recurring delivery needs an operational workflow.","correct":false,"id":"E"},{"text":"Ignore approved-use restrictions if a tool offers better charts.","why":"Organisational constraints remain relevant.","correct":false,"id":"F"},{"text":"Consider the team’s skills, ownership, licensing and maintenance.","why":"The best outcome includes ongoing support.","correct":true,"id":"G"},{"text":"Say code is always better than licensed reporting software.","why":"Both have trade-offs.","correct":false,"id":"H"}],"answer":"Compare available options against connectivity, reproducibility, security and sharing needs. Consider the team’s skills, ownership, licensing and maintenance. Apply a justified approved tool or combination and evaluate its delivered result.","source":{"anchor":"ksb-s15","guideSha256":"57328e157ecc1d18b4913049441798285a61136023fe24c5a86de23aca366ccb","excerpt":"Show the decision process and then show that you applied the selected tool."}},{"id":"T07-Q08","ksb":"K11","prompt":"Which statements fairly compare licensed tools and custom code?","options":[{"text":"Organisational availability is irrelevant if a tool can be downloaded.","why":"Availability and permission are material constraints.","correct":false,"id":"A"},{"text":"Tool popularity proves suitability for confidential data.","why":"Approved use and controls must be assessed.","correct":false,"id":"B"},{"text":"Open-source code has no maintenance cost.","why":"Support and testing still require effort.","correct":false,"id":"C"},{"text":"Code may provide flexible, versionable analysis but still needs testing and support.","why":"Flexibility does not remove lifecycle costs.","correct":true,"id":"D"},{"text":"A licensed tool may provide support and familiar governed sharing.","why":"These can benefit delivery and maintenance.","correct":true,"id":"E"},{"text":"A custom script is reproducible even when inputs and transformations are undocumented.","why":"Reproducibility needs a traceable workflow.","correct":false,"id":"F"},{"text":"A software licence guarantees every statistical method required.","why":"Capabilities need checking.","correct":false,"id":"G"},{"text":"Evaluate both against the organisation’s permitted tools and the project constraints.","why":"There is no universally superior option.","correct":true,"id":"H"}],"answer":"A licensed tool may provide support and familiar governed sharing. Code may provide flexible, versionable analysis but still needs testing and support. Evaluate both against the organisation’s permitted tools and the project constraints.","source":{"anchor":"ksb-k11","guideSha256":"bc1a99c3c235c6421238572df4d834ea21e8a317a4c5f38e689e95adc86b5d96","excerpt":"Describe tools your organisation actually makes available, then compare them against the analytical requirement."}},{"id":"T07-Q09","ksb":"S14","prompt":"A manager compares weekly volumes across services. Which comparison of visual representations is defensible?","options":[{"text":"Grouped bars can support comparisons between service categories within a week.","why":"They make category magnitudes easy to compare.","correct":true,"id":"A"},{"text":"Change the underlying totals between charts to make the preferred design look clearer.","why":"That is not a fair representation comparison.","correct":false,"id":"B"},{"text":"The most decorative chart always gives the strongest stakeholder insight.","why":"Suitability depends on the question and user.","correct":false,"id":"C"},{"text":"Two screenshots alone demonstrate the full rationale for a choice.","why":"The audience, construction and implications need explanation.","correct":false,"id":"D"},{"text":"Colour alone is sufficient to distinguish every service.","why":"Labels, patterns or other cues improve access.","correct":false,"id":"E"},{"text":"Use the same underlying values and explain what each representation reveals, hides and requires for accessibility.","why":"A meaningful comparison needs consistent data and explicit reasoning.","correct":true,"id":"F"},{"text":"A line chart proves that the pattern will continue into future weeks.","why":"Observed change is not automatically a forecast.","correct":false,"id":"G"},{"text":"A suitably labelled line representation can emphasise change over the ordered weeks.","why":"Time order supports a trend view.","correct":true,"id":"H"}],"answer":"Grouped bars can support comparisons between service categories within a week. A suitably labelled line representation can emphasise change over the ordered weeks. Use the same underlying values and explain what each representation reveals, hides and requires for accessibility.","source":{"anchor":"ksb-s14","guideSha256":"fe8ae3c33cc1c8e2bd105b901a97f94b26b72e1bf2336b438fdcac2217923fbd","excerpt":"Quantitative data measures quantities such as counts or durations."}},{"id":"T07-Q10","ksb":"K7","prompt":"Which explanation correctly treats accessibility as part of UX?","options":[{"text":"A tool’s default template proves the finished output is accessible.","why":"The actual output needs evaluation.","correct":false,"id":"A"},{"text":"Users need understandable labels, definitions and suitable alternatives to visual-only content.","why":"Clarity and access support the task.","correct":true,"id":"B"},{"text":"Domain context is irrelevant once typography is readable.","why":"Useful meaning still depends on the domain.","correct":false,"id":"C"},{"text":"Consider contrast, non-colour cues, readable text and keyboard interaction where relevant.","why":"Different abilities and technologies need consideration.","correct":true,"id":"D"},{"text":"Colour contrast alone addresses every accessibility requirement.","why":"Other content and interaction needs remain.","correct":false,"id":"E"},{"text":"Accessibility is only relevant when a stakeholder has declared a disability.","why":"Inclusive use should not rely on a prior declaration.","correct":false,"id":"F"},{"text":"Explain the checks and limitations for the actual output rather than assuming compliance.","why":"Design intent is different from verified usability.","correct":true,"id":"G"},{"text":"Removing all detail automatically improves clarity.","why":"Necessary definitions and limitations can be essential.","correct":false,"id":"H"}],"answer":"Users need understandable labels, definitions and suitable alternatives to visual-only content. Consider contrast, non-colour cues, readable text and keyboard interaction where relevant. Explain the checks and limitations for the actual output rather than assuming compliance.","source":{"anchor":"ksb-k7","guideSha256":"26566e062e02e7cd9279db6718c4d57db2e930bf92599ca1857023e0b5972db6","excerpt":"UX is how well a person can understand and use an output to complete a task."}}]},{"id":"T08","title":"Professional behaviours","description":"Security, adaptability, reasoning, collaboration and reflection in realistic situations.","questions":[{"id":"T08-Q01","ksb":"B1","prompt":"An analyst is leaving a shared desk briefly. Which actions demonstrate secure everyday behaviour?","options":[{"text":"Lock the unattended screen and protect authentication details.","why":"Physical and account access both need protection.","correct":true,"id":"A"},{"text":"Leave the session open because the room is inside the organisation.","why":"Internal location does not remove access risk.","correct":false,"id":"B"},{"text":"Assume secure behaviour applies only to final published reports.","why":"Working copies and meetings also matter.","correct":false,"id":"C"},{"text":"Share a password with a colleague to keep work moving.","why":"Credential sharing weakens accountability.","correct":false,"id":"D"},{"text":"Follow incident and retention procedures and clarify uncertain access through the agreed route.","why":"Professional handling continues throughout the work.","correct":true,"id":"E"},{"text":"Keep identifying extracts on an unmanaged personal device.","why":"Use approved storage and devices.","correct":false,"id":"F"},{"text":"Delete an incident record so the team does not look unproductive.","why":"Use the agreed reporting process honestly.","correct":false,"id":"G"},{"text":"Keep working files and sharing within approved locations and permissions.","why":"Convenience does not replace controls.","correct":true,"id":"H"}],"answer":"Lock the unattended screen and protect authentication details. Keep working files and sharing within approved locations and permissions. Follow incident and retention procedures and clarify uncertain access through the agreed route.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."}},{"id":"T08-Q02","ksb":"B2","prompt":"A usual tool is temporarily unavailable. Which account demonstrates adapting to a minor operational obstacle?","options":[{"text":"Invent a tool failure because routine work is too simple for an example.","why":"The scenario must be genuine in a personal account.","correct":false,"id":"A"},{"text":"Describe only the inconvenience without saying what you changed.","why":"The behaviour needs an adaptive response.","correct":false,"id":"B"},{"text":"Claim the alternative worked without checking its outputs.","why":"Quality must be maintained.","correct":false,"id":"C"},{"text":"Communicate progress, limits or a need for escalation.","why":"Keeping others informed supports productive work.","correct":true,"id":"D"},{"text":"Hide a missed essential requirement to preserve the appearance of progress.","why":"Limitations need communication.","correct":false,"id":"E"},{"text":"Use an approved feasible alternative and validate that it still meets the requirement.","why":"Adaptability should protect quality.","correct":true,"id":"F"},{"text":"Install an unapproved service and upload workplace data immediately.","why":"An obstacle does not authorise bypassing controls.","correct":false,"id":"G"},{"text":"Describe the obstacle, its effect and options within your responsibility.","why":"The adjustment needs a specific context.","correct":true,"id":"H"}],"answer":"Describe the obstacle, its effect and options within your responsibility. Use an approved feasible alternative and validate that it still meets the requirement. Communicate progress, limits or a need for escalation.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."}},{"id":"T08-Q03","ksb":"B3","prompt":"Which statements balance independent responsibility and teamwork?","options":[{"text":"Recognise dependencies and coordinate with the relevant people.","why":"Independence and collaboration are compatible.","correct":true,"id":"A"},{"text":"Wait for detailed instructions before making any routine analytical decision.","why":"Initiative can be part of responsible independence.","correct":false,"id":"B"},{"text":"Invent praise to demonstrate a positive effect on others.","why":"Use actual feedback or observed effects.","correct":false,"id":"C"},{"text":"Organise your assigned tasks and explain decisions you personally made.","why":"This makes independent contribution visible.","correct":true,"id":"D"},{"text":"Say only “we delivered the dashboard” without describing your actions.","why":"That obscures personal contribution.","correct":false,"id":"E"},{"text":"Explain a genuine effect on colleagues’ workload, understanding or delivery.","why":"The behaviour includes considering others.","correct":true,"id":"F"},{"text":"Treat the team’s entire output as your individual achievement.","why":"Contributions need accurate attribution.","correct":false,"id":"G"},{"text":"Avoid collaboration even when the source owner must clarify a definition.","why":"Appropriate collaboration can be necessary.","correct":false,"id":"H"}],"answer":"Organise your assigned tasks and explain decisions you personally made. Recognise dependencies and coordinate with the relevant people. Explain a genuine effect on colleagues’ workload, understanding or delivery.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."}},{"id":"T08-Q04","ksb":"B4","prompt":"Which account demonstrates logical thinking when an analytical result is uncertain?","options":[{"text":"Explain the conclusion, limitations and a feasible alternative approach.","why":"A defensible account includes rationale and trade-offs.","correct":true,"id":"A"},{"text":"Ignore stakeholder consequences when evaluating an alternative.","why":"The practical outcome matters.","correct":false,"id":"B"},{"text":"Form candidate explanations and state why each proposed check is relevant.","why":"Reasoning should connect the problem to tests.","correct":true,"id":"C"},{"text":"Sequence checks and revise judgement in response to evidence.","why":"Each step should follow from what was learned.","correct":true,"id":"D"},{"text":"Keep the first explanation because changing your mind looks indecisive.","why":"Evidence can justify revising judgement.","correct":false,"id":"E"},{"text":"Report only the final answer with no supporting checks.","why":"The logic needs to be visible.","correct":false,"id":"F"},{"text":"Change every parameter until the result matches an expectation.","why":"That does not establish a reasoned solution.","correct":false,"id":"G"},{"text":"Assume a complex diagram proves the reasoning is valid.","why":"Presentation is not evidence of logical validity.","correct":false,"id":"H"}],"answer":"Form candidate explanations and state why each proposed check is relevant. Sequence checks and revise judgement in response to evidence. Explain the conclusion, limitations and a feasible alternative approach.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."}},{"id":"T08-Q05","ksb":"B5","prompt":"Which elements belong in a complete root-cause investigation?","options":[{"text":"Gather evidence and test competing explanations.","why":"A plausible story is not proof.","correct":true,"id":"A"},{"text":"Treat the first Five Whys answer as conclusive evidence.","why":"The framework organises thinking but does not prove causation.","correct":false,"id":"B"},{"text":"Guarantee the problem can never return after one successful run.","why":"Monitoring is needed and absolute guarantees are unwarranted.","correct":false,"id":"C"},{"text":"Stop after hiding the visible symptom.","why":"The underlying cause may remain.","correct":false,"id":"D"},{"text":"Implement an authorised correction and verify its immediate effect.","why":"The proposed fix needs validation.","correct":true,"id":"E"},{"text":"Introduce prevention or monitoring with an owner and examine subsequent results.","why":"Recurrence controls extend beyond a one-off correction.","correct":true,"id":"F"},{"text":"Change source systems without authority.","why":"Corrections need the approved route.","correct":false,"id":"G"},{"text":"Define and reproduce the issue while separating the symptom from possible causes.","why":"A clear problem supports focused investigation.","correct":true,"id":"H"}],"answer":"Define and reproduce the issue while separating the symptom from possible causes. Gather evidence and test competing explanations. Implement an authorised correction and verify its immediate effect. Introduce prevention or monitoring with an owner and examine subsequent results.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."}},{"id":"T08-Q06","ksb":"B6","prompt":"Which account demonstrates resilience after an analytical setback?","options":[{"text":"Use feedback and manageable steps while maintaining quality.","why":"Persistence should include adaptation, not blind repetition.","correct":true,"id":"A"},{"text":"Claim you never found any aspect difficult.","why":"That does not demonstrate a response to a challenge.","correct":false,"id":"B"},{"text":"Present an unsuccessful method as successful to avoid embarrassment.","why":"Honest reporting matters.","correct":false,"id":"C"},{"text":"State “I learned a lot” without identifying any lesson or later change.","why":"A reflection needs concrete learning.","correct":false,"id":"D"},{"text":"Describe the actual challenge and a constructive response such as reassessment or seeking support.","why":"Specific actions demonstrate resilience.","correct":true,"id":"E"},{"text":"Explain a lesson and a concrete change to later practice, including imperfect outcomes honestly.","why":"Learning need not depend on a perfect initial result.","correct":true,"id":"F"},{"text":"Treat support from others as evidence of failure.","why":"Appropriate help can support resilience.","correct":false,"id":"G"},{"text":"Repeat the same failed approach without considering feedback.","why":"Constructive adaptation is more useful.","correct":false,"id":"H"}],"answer":"Describe the actual challenge and a constructive response such as reassessment or seeking support. Use feedback and manageable steps while maintaining quality. Explain a lesson and a concrete change to later practice, including imperfect outcomes honestly.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."}},{"id":"T08-Q07","ksb":"B7","prompt":"Which elements demonstrate flexibility when organisational priorities change?","options":[{"text":"Reassess requirements, methods, risks and timescales.","why":"Broader changes can affect the whole plan.","correct":true,"id":"A"},{"text":"Describe only a brief missing-file issue with no wider shift.","why":"That is more directly a B2 operational example.","correct":false,"id":"B"},{"text":"Omit limitations because the revised goal is important.","why":"Material limitations remain relevant.","correct":false,"id":"C"},{"text":"Agree a revised approach and manage stakeholder feedback and expectations.","why":"Adaptation needs communication and agreement.","correct":true,"id":"D"},{"text":"Assume every original deliverable is still equally urgent.","why":"Changed priorities may require renegotiation.","correct":false,"id":"E"},{"text":"Describe the original responsibilities or scope and the new direction.","why":"The contextual shift needs to be clear.","correct":true,"id":"F"},{"text":"Change the scope silently to avoid a difficult conversation.","why":"Stakeholders need aligned expectations.","correct":false,"id":"G"},{"text":"Explain your own changed actions, trade-offs and the outcome.","why":"The account should show what you actually adapted.","correct":true,"id":"H"}],"answer":"Describe the original responsibilities or scope and the new direction. Reassess requirements, methods, risks and timescales. Agree a revised approach and manage stakeholder feedback and expectations. Explain your own changed actions, trade-offs and the outcome.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."}},{"id":"T08-Q08","ksb":"K2","prompt":"A colleague suggests an online AI tool for workplace comments. Which organisational-policy reasoning is sound?","options":[{"text":"Check whether the tool and proposed data use are actually permitted.","why":"Public availability is not organisational approval.","correct":true,"id":"A"},{"text":"Follow the current AI, information-security and data-handling policies or seek clarification from the responsible role.","why":"Actual rules govern the decision.","correct":true,"id":"B"},{"text":"Explain how non-compliance could harm people, services, trust or regulatory obligations.","why":"The consequences give the policy practical significance.","correct":true,"id":"C"},{"text":"Describe a policy as optional advice whenever a deadline is tight.","why":"Follow the applicable approved rules.","correct":false,"id":"D"},{"text":"Upload the full data first and request approval afterwards.","why":"Controls should shape use before disclosure.","correct":false,"id":"E"},{"text":"Assume an AI policy replaces all retention and sharing policies.","why":"Relevant policies operate together.","correct":false,"id":"F"},{"text":"Copy another employer’s rules into your answer as your own.","why":"The organisational account must be accurate.","correct":false,"id":"G"},{"text":"Use the tool because it has a professional-looking privacy page.","why":"That does not establish workplace authorisation.","correct":false,"id":"H"}],"answer":"Check whether the tool and proposed data use are actually permitted. Follow the current AI, information-security and data-handling policies or seek clarification from the responsible role. Explain how non-compliance could harm people, services, trust or regulatory obligations.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."}},{"id":"T08-Q09","ksb":"S12","prompt":"An urgent quality issue affects a manager’s decision and needs a data engineer’s investigation. Which communication is appropriate?","options":[{"text":"Give the engineer relevant technical evidence about the source, grain or transformation.","why":"Investigation needs diagnostic detail.","correct":true,"id":"A"},{"text":"Wait for the next routine presentation even if the current decision is affected.","why":"Urgency can require a different channel.","correct":false,"id":"B"},{"text":"Give the manager a clear account of affected outputs, limits and the immediate decision risk.","why":"The decision-maker needs usable implications.","correct":true,"id":"C"},{"text":"Use a channel suited to urgency and record agreed ownership or next actions.","why":"Context and follow-up support collaboration.","correct":true,"id":"D"},{"text":"Describe only the messages sent and omit responses or actions.","why":"Communication includes feedback and effect.","correct":false,"id":"E"},{"text":"Claim two copies of the same message to one person demonstrate two stakeholders.","why":"The contrast requires distinct stakeholders.","correct":false,"id":"F"},{"text":"Remove caveats from the manager’s message to avoid concern.","why":"Material risks should be explained.","correct":false,"id":"G"},{"text":"Send everyone the same unexplained stack trace.","why":"Technical detail needs audience-appropriate interpretation.","correct":false,"id":"H"}],"answer":"Give the manager a clear account of affected outputs, limits and the immediate decision risk. Give the engineer relevant technical evidence about the source, grain or transformation. Use a channel suited to urgency and record agreed ownership or next actions.","source":{"anchor":"ksb-s12","guideSha256":"3eb2f4c5da12f2a05c97da6f15657d048685f3b46342a8ed73abb499f2680160","excerpt":"Show communication with at least two distinct stakeholders as requested in the supplied preparation guide, and cover all relevant stakeholders for the work."}},{"id":"T08-Q10","ksb":"S6","prompt":"A data issue cannot be resolved within your authority before delivery. Which actions complete a responsible escalation?","options":[{"text":"Alter source-system values without permission to avoid delay.","why":"Follow the authorised correction route.","correct":false,"id":"A"},{"text":"Describe an interim mitigation, the responsible owner and the required next action.","why":"Escalation should be actionable.","correct":true,"id":"B"},{"text":"Hide the affected outputs so the report appears complete.","why":"Decision-makers need material limitations.","correct":false,"id":"C"},{"text":"Claim the issue is resolved merely because another team was notified.","why":"Escalation and resolution are different states.","correct":false,"id":"D"},{"text":"Preserve the source and record checks, transformations and residual limitations.","why":"A traceable record supports resolution and later validation.","correct":true,"id":"E"},{"text":"Escalate a vague “data is wrong” message with no evidence or impact.","why":"A useful escalation needs detail and context.","correct":false,"id":"F"},{"text":"Discard the original extract so no one can reproduce the issue.","why":"Preserving the source supports investigation.","correct":false,"id":"G"},{"text":"Explain the issue’s scale, affected outputs and potential decision impact.","why":"The recipient needs to understand the risk.","correct":true,"id":"H"}],"answer":"Explain the issue’s scale, affected outputs and potential decision impact. Describe an interim mitigation, the responsible owner and the required next action. Preserve the source and record checks, transformations and residual limitations.","source":{"anchor":"ksb-s6","guideSha256":"dc73f26172b8e4a54be65d1401e4ce48334bb00e7eafdface7d2f4064df7d492","excerpt":"Demonstrate a complete issue-handling loop: detect, measure, assess impact, investigate, mitigate or escalate, resolve where authorised, and validate."}}]},{"id":"T09","title":"Applied analytical decisions","description":"Practical checks across the first ten Skills, using fictional workplace situations.","questions":[{"id":"T09-Q01","ksb":"S1","prompt":"A project’s purpose changes after an extract has been approved. Which compliant response is appropriate?","options":[{"text":"Apply approved transfers, disclosure checks and retention to the revised workflow.","why":"Controls need to cover the updated lifecycle.","correct":true,"id":"A"},{"text":"Wait until publication to consider the changed privacy risk.","why":"Risk should shape the design earlier.","correct":false,"id":"B"},{"text":"Bypass the required privacy assessment because one was considered for the old purpose.","why":"Changed scope may require a new review under the actual process.","correct":false,"id":"C"},{"text":"Describe pseudonymised data as outside all privacy controls.","why":"It may remain personal data.","correct":false,"id":"D"},{"text":"Copy all additional fields first so approvals do not slow exploration.","why":"Minimisation and authorisation should guide acquisition.","correct":false,"id":"E"},{"text":"Review whether the new purpose, fields and access are still authorised.","why":"Original approval does not cover every changed use.","correct":true,"id":"F"},{"text":"Assume access to the old extract authorises any new analysis.","why":"Purpose and usage limits remain relevant.","correct":false,"id":"G"},{"text":"Reassess privacy risks and involve the relevant owner or protection role where required.","why":"Privacy by Design includes scope changes.","correct":true,"id":"H"}],"answer":"Review whether the new purpose, fields and access are still authorised. Reassess privacy risks and involve the relevant owner or protection role where required. Apply approved transfers, disclosure checks and retention to the revised workflow.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."}},{"id":"T09-Q02","ksb":"S2","prompt":"Which account completes the lifecycle beyond producing an analytical result?","options":[{"text":"Describe reconciliation, comparisons, feedback and resulting refinements.","why":"A completed calculation still needs validation.","correct":true,"id":"A"},{"text":"List stage names without explaining personal actions.","why":"S2 requires application.","correct":false,"id":"B"},{"text":"Connect the result back to the agreed question and success criteria.","why":"Analysis should answer the original decision need.","correct":true,"id":"C"},{"text":"Describe a fictional worked example as an actual delivered project.","why":"Personal evidence must remain genuine.","correct":false,"id":"D"},{"text":"End the account at the first chart because communication is unrelated to analysis.","why":"The guide includes communication and implementation.","correct":false,"id":"E"},{"text":"Claim every project must contain the same model type.","why":"Method choice depends on the question and source requirements.","correct":false,"id":"F"},{"text":"Explain audience-appropriate delivery, limitations and handover or review.","why":"Use and communication complete the lifecycle chain.","correct":true,"id":"G"},{"text":"Treat feedback as a reason to skip preparation checks.","why":"Feedback may instead reveal a need to revisit them.","correct":false,"id":"H"}],"answer":"Connect the result back to the agreed question and success criteria. Describe reconciliation, comparisons, feedback and resulting refinements. Explain audience-appropriate delivery, limitations and handover or review.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."}},{"id":"T09-Q03","ksb":"S3","prompt":"A colleague proposes sharing a pseudonymised extract more widely. Which reasoning is required?","options":[{"text":"Use the research label as permission for unrestricted sharing.","why":"Purpose categories do not replace handling controls.","correct":false,"id":"A"},{"text":"Apply the organisation’s actual classification and approved access rules.","why":"A renamed identifier does not decide permissions.","correct":true,"id":"B"},{"text":"Assume small group counts cannot disclose anything.","why":"Rare combinations or linkage can still identify individuals.","correct":false,"id":"C"},{"text":"Treat pseudonymisation as a guarantee of anonymity.","why":"The guide explicitly distinguishes the concepts.","correct":false,"id":"D"},{"text":"Assume all staff can access records with numeric IDs.","why":"Identifiers can still link to people.","correct":false,"id":"E"},{"text":"Delete the classification note because the names are gone.","why":"Accountability for handling remains useful.","correct":false,"id":"F"},{"text":"Justify any approved change in handling and document remaining risks.","why":"The proposed use needs a reasoned decision.","correct":true,"id":"G"},{"text":"Check identifiability, linkable fields and the separately controlled lookup.","why":"Pseudonymisation may leave re-identification possible.","correct":true,"id":"H"}],"answer":"Check identifiability, linkable fields and the separately controlled lookup. Apply the organisation’s actual classification and approved access rules. Justify any approved change in handling and document remaining risks.","source":{"anchor":"ksb-s3","guideSha256":"6e7245ee3fe6dc9da12b01ab547600adaa1bbf9400a7ecf58a49c2ba5d8fe83f","excerpt":"Assess sensitivity, identifiability, purpose, access and potential harm, then apply your organisation's real classification and handling scheme."}},{"id":"T09-Q04","ksb":"S4","prompt":"Which explanation demonstrates adapting analysis to a table, nested JSON and free text?","options":[{"text":"Cite different filenames as sufficient proof of different database designs.","why":"File names do not establish structural differences.","correct":false,"id":"A"},{"text":"Assume NoSQL removes all design and governance responsibilities.","why":"Those responsibilities remain.","correct":false,"id":"B"},{"text":"Claim an ERD proves you personally designed the database.","why":"Describe the work you actually performed.","correct":false,"id":"C"},{"text":"Use appropriate joins, flattening or thematic coding according to the structure and question.","why":"Different structures can require different techniques.","correct":true,"id":"D"},{"text":"Use identical transformation steps regardless of data structure.","why":"The approach must account for the differences.","correct":false,"id":"E"},{"text":"Validate the transformation’s effect on counts and meaning and explain the benefit.","why":"Adaptation should solve a problem without distorting the analysis.","correct":true,"id":"F"},{"text":"Treat expanded nested children as new parent entities.","why":"That can change the grain incorrectly.","correct":false,"id":"G"},{"text":"Describe each source’s schema, grain, types and extracted shape.","why":"These determine suitable handling.","correct":true,"id":"H"}],"answer":"Describe each source’s schema, grain, types and extracted shape. Use appropriate joins, flattening or thematic coding according to the structure and question. Validate the transformation’s effect on counts and meaning and explain the benefit.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."}},{"id":"T09-Q05","ksb":"S5","prompt":"A stakeholder says a dashboard is hard to interpret. Which response demonstrates applying UX?","options":[{"text":"Hide refresh timing to reduce visual clutter.","why":"Users need important context about currency.","correct":false,"id":"A"},{"text":"Invent user feedback to show a successful revision.","why":"The account should describe actual feedback.","correct":false,"id":"B"},{"text":"Add more decorative charts without identifying the difficulty.","why":"Decoration may increase cognitive burden.","correct":false,"id":"C"},{"text":"Treat the user’s domain vocabulary as irrelevant.","why":"Language and definitions influence understanding.","correct":false,"id":"D"},{"text":"Clarify the task and domain definitions behind the stakeholder’s difficulty.","why":"Feedback should be understood in context.","correct":true,"id":"E"},{"text":"Revise hierarchy, labels, filter visibility or non-colour cues as appropriate.","why":"Specific choices should address the problem.","correct":true,"id":"F"},{"text":"Declare accessibility compliance because the palette changed.","why":"Conformance needs appropriate checks.","correct":false,"id":"G"},{"text":"Test the revised output with intended users and document the actual improvement and limitations.","why":"A change needs evidence of useful effect.","correct":true,"id":"H"}],"answer":"Clarify the task and domain definitions behind the stakeholder’s difficulty. Revise hierarchy, labels, filter visibility or non-colour cues as appropriate. Test the revised output with intended users and document the actual improvement and limitations.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."}},{"id":"T09-Q06","ksb":"S6","prompt":"A lookup contains conflicting names for one service ID. Which handling is defensible?","options":[{"text":"Quantify the conflict and its effect on joins or reported categories.","why":"Understand the decision impact before treatment.","correct":true,"id":"A"},{"text":"Treat a query that executes successfully as proof the conflict is harmless.","why":"Syntactic success does not establish analytical correctness.","correct":false,"id":"B"},{"text":"Keep whichever name appears first in the file without explanation.","why":"File order does not establish authority.","correct":false,"id":"C"},{"text":"Delete every request using the service ID to remove the warning.","why":"That can exclude valid cases and hide the issue.","correct":false,"id":"D"},{"text":"Overwrite the source without recording the decision.","why":"Preserve lineage and follow authorised controls.","correct":false,"id":"E"},{"text":"Apply a blanket adjustment to totals rather than fixing the relationship.","why":"The structural cause remains.","correct":false,"id":"F"},{"text":"Seek an authoritative resolution or escalate to the source owner.","why":"An arbitrary value choice is not a validated fix.","correct":true,"id":"G"},{"text":"Re-run uniqueness, cardinality and output checks after the approved treatment.","why":"Resolution must be validated.","correct":true,"id":"H"}],"answer":"Quantify the conflict and its effect on joins or reported categories. Seek an authoritative resolution or escalate to the source owner. Re-run uniqueness, cardinality and output checks after the approved treatment.","source":{"anchor":"ksb-s6","guideSha256":"dc73f26172b8e4a54be65d1401e4ce48334bb00e7eafdface7d2f4064df7d492","excerpt":"Demonstrate a complete issue-handling loop: detect, measure, assess impact, investigate, mitigate or escalate, resolve where authorised, and validate."}},{"id":"T09-Q07","ksb":"S7","prompt":"A user asks for an extra feature two days before delivery. Which response keeps requirements connected to the plan?","options":[{"text":"Agree and document the revised scope, deliverable and checks or explain the deferral.","why":"Requirements changes should be managed explicitly.","correct":true,"id":"A"},{"text":"Reject all changes because the first brief can never be revised.","why":"An agreed change route allows appropriate revision.","correct":false,"id":"B"},{"text":"Drop an essential validation step to make room for decoration.","why":"Quality controls should remain defensible.","correct":false,"id":"C"},{"text":"Clarify the decision the feature would support and its priority.","why":"A feature request should be related to a need.","correct":true,"id":"D"},{"text":"Assess time, data access, method and acceptance implications with the stakeholder.","why":"A change can affect scope and feasibility.","correct":true,"id":"E"},{"text":"Accept every feature without revisiting the deadline.","why":"Uncontrolled expansion can undermine delivery.","correct":false,"id":"F"},{"text":"Call the feature delivered merely because a button is visible.","why":"Acceptance concerns the intended behaviour and decision.","correct":false,"id":"G"},{"text":"Change the methodology silently and hope the user does not notice.","why":"Material changes need communication.","correct":false,"id":"H"}],"answer":"Clarify the decision the feature would support and its priority. Assess time, data access, method and acceptance implications with the stakeholder. Agree and document the revised scope, deliverable and checks or explain the deferral.","source":{"anchor":"ksb-s7","guideSha256":"762c5d5a314f38868448a38aed918ae5c309770463d456b02ece5c88cba6bd1f","excerpt":"Show a chain from a stated need to planned method, output and acceptance check."}},{"id":"T09-Q08","ksb":"S8","prompt":"Two monthly extracts use differently formatted keys and units. Which preparation supports a robust combination?","options":[{"text":"Treat unmatched rows as errors to delete automatically.","why":"Their meaning and impact need investigation.","correct":false,"id":"A"},{"text":"Ignore duplicate lookup keys if the final report is small.","why":"Duplicates can distort totals at any scale.","correct":false,"id":"B"},{"text":"Convert every key to a number even when leading zeroes carry meaning.","why":"That can destroy legitimate identifiers.","correct":false,"id":"C"},{"text":"Check key types, formatting, grain, periods and business meanings.","why":"Technical and semantic compatibility both matter.","correct":true,"id":"D"},{"text":"Reconcile counts, unmatched keys and important totals afterwards.","why":"Combining data requires output validation.","correct":true,"id":"E"},{"text":"Assume matching column names guarantee matching units.","why":"Labels do not establish semantic compatibility.","correct":false,"id":"F"},{"text":"Use UNION as a synonym for a key-based join.","why":"Appending rows and joining records are different operations.","correct":false,"id":"G"},{"text":"Apply documented justified cleaning or unit conversions before the chosen join.","why":"Transformations should preserve meaning.","correct":true,"id":"H"}],"answer":"Check key types, formatting, grain, periods and business meanings. Apply documented justified cleaning or unit conversions before the chosen join. Reconcile counts, unmatched keys and important totals afterwards.","source":{"anchor":"ksb-s8","guideSha256":"0f5cddb86161986b79351977142757eead70691fc156a7d038e573f11ffcd428","excerpt":"Demonstrate a repeatable join in an appropriate tool, with explicit keys, grain and validation."}},{"id":"T09-Q09","ksb":"S9","prompt":"A BI report connects to a governed database through an approved gateway. What belongs in the explanation?","options":[{"text":"Explain least privilege, query or refresh constraints and where transformations run.","why":"Infrastructure and controls shape the workflow.","correct":true,"id":"A"},{"text":"Treat querying a managed database as proof you maintain all its infrastructure.","why":"Do not invent administration duties.","correct":false,"id":"B"},{"text":"Claim the gateway removes all access restrictions.","why":"Approved connectivity does not mean unrestricted access.","correct":false,"id":"C"},{"text":"Publish credentials as evidence that the connection worked.","why":"Protect authentication details.","correct":false,"id":"D"},{"text":"Describe a generic cloud diagram instead of the actual workflow.","why":"S9 needs a concrete interaction with architecture.","correct":false,"id":"E"},{"text":"Identify the database component, supported connector and the relevant authentication approach.","why":"The account should describe the real connection.","correct":true,"id":"F"},{"text":"Justify the choice and accurately distinguish your analyst role from administration.","why":"Tool use should match actual responsibilities.","correct":true,"id":"G"},{"text":"Assume every connector can reach every source without configuration.","why":"Compatibility and platform constraints matter.","correct":false,"id":"H"}],"answer":"Identify the database component, supported connector and the relevant authentication approach. Explain least privilege, query or refresh constraints and where transformations run. Justify the choice and accurately distinguish your analyst role from administration.","source":{"anchor":"ksb-s9","guideSha256":"71edb943dfa86f21da3b61052db03a37b8a51cb0ecbfb3ae823aafcd6a641aa9","excerpt":"Explain which tool you used to interact with which architectural component and why the connection satisfied the organisation's constraints."}},{"id":"T09-Q10","ksb":"S10","prompt":"Which interpretation would connect statistical analysis to a business decision responsibly?","options":[{"text":"Conclude causation from any observed correlation.","why":"Association requires further reasoning before causal claims.","correct":false,"id":"A"},{"text":"Explain the question, hypotheses, method choice and relevant assumptions.","why":"The analysis should have an explicit purpose and design.","correct":true,"id":"B"},{"text":"Treat a p-value below alpha as proof the effect is large.","why":"Magnitude needs an effect estimate.","correct":false,"id":"C"},{"text":"Report the estimated effect and uncertainty alongside the p-value.","why":"Statistical significance alone does not express the size or precision.","correct":true,"id":"D"},{"text":"Discuss practical importance and possible decision-error consequences.","why":"The business needs an interpretation, not only software output.","correct":true,"id":"E"},{"text":"Omit sampling limitations because the test function returned a result.","why":"Software output does not establish valid assumptions.","correct":false,"id":"F"},{"text":"Treat a p-value above alpha as proof of no possible useful effect.","why":"Non-rejection is not proof of exact absence.","correct":false,"id":"G"},{"text":"Choose alpha after seeing which value makes the result significant.","why":"The threshold should be planned.","correct":false,"id":"H"}],"answer":"Explain the question, hypotheses, method choice and relevant assumptions. Report the estimated effect and uncertainty alongside the p-value. Discuss practical importance and possible decision-error consequences.","source":{"anchor":"ksb-s10","guideSha256":"c42a163b39508febe898efed0feb19bdc5dadb606e898701905c94e865897acc","excerpt":"Start with EDA: check shape, data types, missingness, duplicates, distributions, outliers, groups and possible sampling bias."}}]},{"id":"T10","title":"Mixed EPA revision","description":"Connect systems, analysis, ethics and reflection without overclaiming what the evidence shows.","questions":[{"id":"T10-Q01","ksb":"K6","prompt":"Which statements correctly connect database implementation, maintenance and access?","options":[{"text":"Maintenance includes monitored pipelines, validated loads and managed schema changes.","why":"A working database requires ongoing controls.","correct":true,"id":"A"},{"text":"ETL means extracting only the final chart image.","why":"It concerns extracting, transforming and loading data.","correct":false,"id":"B"},{"text":"Implementation includes grain, field types, keys, constraints, indexes and access roles.","why":"Design decisions affect storage and querying.","correct":true,"id":"C"},{"text":"Normalisation is the process of making every numeric distribution normal.","why":"Database normalisation concerns relational structure.","correct":false,"id":"D"},{"text":"Users can interact through authorised SQL queries or APIs and BI connections; ETL transforms before loading.","why":"Access methods and pipeline order should be explained precisely.","correct":true,"id":"E"},{"text":"A warehouse and an operational database must have identical purposes and schemas.","why":"Analytical and operational needs can differ.","correct":false,"id":"F"},{"text":"Once implemented, database systems need no load or access monitoring.","why":"Ongoing maintenance remains necessary.","correct":false,"id":"G"},{"text":"NoSQL means that no schema or design decisions are ever required.","why":"Non-relational systems still require design and governance.","correct":false,"id":"H"}],"answer":"Implementation includes grain, field types, keys, constraints, indexes and access roles. Maintenance includes monitored pipelines, validated loads and managed schema changes. Users can interact through authorised SQL queries or APIs and BI connections; ETL transforms before loading.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."}},{"id":"T10-Q02","ksb":"K12","prompt":"Which reasoning avoids overstating the need for Big Data architecture?","options":[{"text":"Explain why a modest relational or other approved solution may suit the requirement.","why":"The most complex platform is not automatically necessary.","correct":true,"id":"A"},{"text":"Consider scale, speed and variety in relation to actual storage or processing needs.","why":"These factors can motivate distributed approaches.","correct":true,"id":"B"},{"text":"Treat tool selection as independent of identities and network routes.","why":"Infrastructure constrains feasible access.","correct":false,"id":"C"},{"text":"Ignore retention because central storage has spare capacity.","why":"Capacity does not decide retention obligations.","correct":false,"id":"D"},{"text":"Assume larger storage removes the need for governance or metadata.","why":"Management and quality still matter.","correct":false,"id":"E"},{"text":"Describe the infrastructure the organisation actually uses.","why":"Architecture claims must be grounded.","correct":true,"id":"F"},{"text":"Call every spreadsheet a distributed data lake.","why":"Those concepts are not interchangeable.","correct":false,"id":"G"},{"text":"Include Big Data technologies because every analytical portfolio must use them.","why":"The guide does not impose that claim.","correct":false,"id":"H"}],"answer":"Consider scale, speed and variety in relation to actual storage or processing needs. Describe the infrastructure the organisation actually uses. Explain why a modest relational or other approved solution may suit the requirement.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."}},{"id":"T10-Q03","ksb":"S11","prompt":"Which statements make a predictive recommendation more defensible?","options":[{"text":"Hide the baseline if it outperforms the complex model.","why":"The comparison is material evidence.","correct":false,"id":"A"},{"text":"Choose the model with the lowest training error regardless of holdout results.","why":"Generalisation needs independent evaluation.","correct":false,"id":"B"},{"text":"Claim regression proves the recommended intervention will cause improvement.","why":"Prediction does not alone identify causal effects.","correct":false,"id":"C"},{"text":"Include future outcome fields because they improve accuracy.","why":"That creates unrealistic leakage.","correct":false,"id":"D"},{"text":"Assume an accurate prediction determines the ethically correct action automatically.","why":"Decision context and ethical judgement still matter.","correct":false,"id":"E"},{"text":"Compare the candidate model with a suitable baseline on unseen data.","why":"A baseline gives the metric context.","correct":true,"id":"F"},{"text":"Connect the prediction to a feasible action under stated objectives and constraints.","why":"Prediction alone is not a prescription.","correct":true,"id":"G"},{"text":"Check available-at-prediction-time features, subgroup effects and relevant error consequences.","why":"Practical validity includes leakage and affected groups.","correct":true,"id":"H"}],"answer":"Compare the candidate model with a suitable baseline on unseen data. Check available-at-prediction-time features, subgroup effects and relevant error consequences. Connect the prediction to a feasible action under stated objectives and constraints.","source":{"anchor":"ksb-s11","guideSha256":"6cf9f35febad9dfa76eb76a27e7eeb97d5312845c45dea04f5b5a8390f488a54","excerpt":"Demonstrate a connected descriptive, predictive and prescriptive workflow."}},{"id":"T10-Q04","ksb":"S13","prompt":"Which statements keep forecast training, evaluation and projection separate?","options":[{"text":"Treat a historical fitted line alone as forecast validation.","why":"It does not evaluate unseen observations.","correct":false,"id":"A"},{"text":"Calculate error on later known actuals and compare a baseline on the same observations.","why":"Metrics need a fair common evaluation window.","correct":true,"id":"B"},{"text":"Label the future horizon as uncertain projections and document any later refit separately.","why":"Future estimates and a refitted model are distinct from the original test.","correct":true,"id":"C"},{"text":"Refit on holdout data and still report the original test as untouched.","why":"Those data would then influence fitting.","correct":false,"id":"D"},{"text":"Claim the toy series establishes a calibrated seasonal model for real demand.","why":"The guide makes no such general performance claim.","correct":false,"id":"E"},{"text":"Fit the model using the defined training history and freeze it for the holdout comparison.","why":"The evaluation should test a fixed candidate.","correct":true,"id":"F"},{"text":"Include projected future values as if they were known actuals in RMSE.","why":"Error cannot be measured against unknown outcomes.","correct":false,"id":"G"},{"text":"Use different months for competing models’ RMSE without explaining the difference.","why":"The comparison may no longer be fair.","correct":false,"id":"H"}],"answer":"Fit the model using the defined training history and freeze it for the holdout comparison. Calculate error on later known actuals and compare a baseline on the same observations. Label the future horizon as uncertain projections and document any later refit separately.","source":{"anchor":"ksb-s13","guideSha256":"46cd9f000fc581e86430af6ad25dc0a9ed1c49d6ecee41240ee5c9cf42272384","excerpt":"Define a forecast target, frequency, observation window and horizon."}},{"id":"T10-Q05","ksb":"S14","prompt":"Which choices support a credible combined display of durations and coded feedback?","options":[{"text":"Present numeric theme codes as if their mean measured sentiment automatically.","why":"Codes may represent unordered categories.","correct":false,"id":"A"},{"text":"Conclude that more complaints always means a lower satisfaction percentage.","why":"Counts require appropriate denominators and context.","correct":false,"id":"B"},{"text":"Choose representations suited to numerical spread and qualitative categories.","why":"Different questions need appropriate visual forms.","correct":true,"id":"C"},{"text":"Preserve privacy and context when using thematic summaries or quotations.","why":"Useful explanation should not expose identifiable people.","correct":true,"id":"D"},{"text":"Use identical chart types for every question regardless of meaning.","why":"Representation should fit the analytical task.","correct":false,"id":"E"},{"text":"Treat all comment samples as representative of all users.","why":"Sampling limits must be assessed.","correct":false,"id":"F"},{"text":"Explain coding rules, denominators, missingness and whether comments may have several themes.","why":"Readers need to understand how measures were produced.","correct":true,"id":"G"},{"text":"Publish rare personal quotations without disclosure checks.","why":"Context can reveal identity.","correct":false,"id":"H"}],"answer":"Choose representations suited to numerical spread and qualitative categories. Explain coding rules, denominators, missingness and whether comments may have several themes. Preserve privacy and context when using thematic summaries or quotations.","source":{"anchor":"ksb-s14","guideSha256":"fe8ae3c33cc1c8e2bd105b901a97f94b26b72e1bf2336b438fdcac2217923fbd","excerpt":"Quantitative data measures quantities such as counts or durations."}},{"id":"T10-Q06","ksb":"S15","prompt":"A manager needs a defensible answer in five days. Which tool decision best follows the guide?","options":[{"text":"Select a method without showing it was applied.","why":"S15 includes actual use.","correct":false,"id":"A"},{"text":"Use an unapproved tool because it offers a fast demonstration.","why":"Approval and safe use remain constraints.","correct":false,"id":"B"},{"text":"State familiarity as the only justification.","why":"Other relevant criteria need consideration.","correct":false,"id":"C"},{"text":"Choose a three-week predictive build solely because it is more sophisticated.","why":"That may miss the actual deadline and decision need.","correct":false,"id":"D"},{"text":"Evaluate the outcome and explain a useful alternative with its benefits, costs and risks.","why":"A reasoned choice includes reflection on trade-offs.","correct":true,"id":"E"},{"text":"Compare feasible approved options against the decision, deadline, data and support constraints.","why":"The requirement defines relevant selection criteria.","correct":true,"id":"F"},{"text":"Choose and apply a maintainable method that can deliver validated results in time.","why":"The best fit need not be the most complex method.","correct":true,"id":"G"},{"text":"Ignore future ownership once the first output is sent.","why":"Maintainability affects the outcome.","correct":false,"id":"H"}],"answer":"Compare feasible approved options against the decision, deadline, data and support constraints. Choose and apply a maintainable method that can deliver validated results in time. Evaluate the outcome and explain a useful alternative with its benefits, costs and risks.","source":{"anchor":"ksb-s15","guideSha256":"57328e157ecc1d18b4913049441798285a61136023fe24c5a86de23aca366ccb","excerpt":"Show the decision process and then show that you applied the selected tool."}},{"id":"T10-Q07","ksb":"K5","prompt":"Which explanation correctly handles structured records and qualitative content in a mixed dataset?","options":[{"text":"Saving a comment in a spreadsheet makes its meaning fully structured.","why":"The storage container does not organise its semantic content.","correct":false,"id":"A"},{"text":"Converting text to themes eliminates all interpretation or bias.","why":"Coding and collection still require judgement and checks.","correct":false,"id":"B"},{"text":"Every numeric-looking category code represents a measurable quantity.","why":"A numeric code may still label a qualitative category.","correct":false,"id":"C"},{"text":"Every JSON export has exactly the same flat relational schema.","why":"JSON can be nested or have varying fields.","correct":false,"id":"D"},{"text":"Filtering and aggregation may suit tabular fields, while text needs coding or extraction with quality and bias checks.","why":"Preparation should fit the content and analytical question.","correct":true,"id":"E"},{"text":"Nested JSON may have named fields and repeated arrays without fitting one flat table.","why":"That is a common semi-structured representation.","correct":true,"id":"F"},{"text":"A request table can have a fixed schema while a comment field contains free-form meaning.","why":"Structured containers can include unstructured content.","correct":true,"id":"G"},{"text":"Unstructured data can never support analysis.","why":"Interpretation and extraction can make analysis possible.","correct":false,"id":"H"}],"answer":"A request table can have a fixed schema while a comment field contains free-form meaning. Nested JSON may have named fields and repeated arrays without fitting one flat table. Filtering and aggregation may suit tabular fields, while text needs coding or extraction with quality and bias checks.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."}},{"id":"T10-Q08","ksb":"B5","prompt":"A one-off correction fixed today’s report. What would strengthen the root-cause account?","options":[{"text":"Describe an authorised preventive check and the role responsible for it.","why":"Prevention should address the mechanism of recurrence.","correct":true,"id":"A"},{"text":"Guarantee there can never be another error after one successful load.","why":"That exceeds the evidence.","correct":false,"id":"B"},{"text":"Claim the cause is established because the output now looks right.","why":"The result alone does not prove the explanation.","correct":false,"id":"C"},{"text":"Treat random row deletion as a preventive control.","why":"It can hide symptoms without fixing the cause.","correct":false,"id":"D"},{"text":"Monitor later results and state residual risk rather than guarantee permanent elimination.","why":"Controls reduce risk but need evaluation.","correct":true,"id":"E"},{"text":"Omit the source-owner role because the analyst noticed the issue.","why":"Authority and ownership still matter.","correct":false,"id":"F"},{"text":"Use a cause diagram as the only evidence.","why":"The diagram organises hypotheses, not proof.","correct":false,"id":"G"},{"text":"Explain evidence linking the underlying process failure to the observed problem.","why":"A correction alone does not establish cause.","correct":true,"id":"H"}],"answer":"Explain evidence linking the underlying process failure to the observed problem. Describe an authorised preventive check and the role responsible for it. Monitor later results and state residual risk rather than guarantee permanent elimination.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."}},{"id":"T10-Q09","ksb":"B6","prompt":"Which reflection demonstrates learning from an imperfect analytical outcome?","options":[{"text":"Use “I will be more careful” without identifying a practical change.","why":"A useful lesson should be actionable.","correct":false,"id":"A"},{"text":"Rewrite an unsuccessful model as a successful deployment.","why":"That would misrepresent the work.","correct":false,"id":"B"},{"text":"Identify a concrete adjustment you used or will apply in later work.","why":"The lesson should influence future practice.","correct":true,"id":"C"},{"text":"Describe only the final outcome and no response to difficulty.","why":"The behaviour concerns how the challenge was handled.","correct":false,"id":"D"},{"text":"Describe the actual setback and constructive actions taken to maintain useful progress.","why":"The account needs a specific challenge and response.","correct":true,"id":"E"},{"text":"State that resilience requires completing every task without help.","why":"Appropriate help can support resilience.","correct":false,"id":"F"},{"text":"Treat a non-optimal result as incapable of supporting reflection.","why":"An honest imperfect outcome can provide useful learning.","correct":false,"id":"G"},{"text":"Explain feedback or support and what the evidence taught you.","why":"Learning can involve other people and changed judgement.","correct":true,"id":"H"}],"answer":"Describe the actual setback and constructive actions taken to maintain useful progress. Explain feedback or support and what the evidence taught you. Identify a concrete adjustment you used or will apply in later work.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."}},{"id":"T10-Q10","ksb":"B7","prompt":"Which account demonstrates managing stakeholder feedback during a broader contextual shift?","options":[{"text":"Describe the revised approach, trade-offs and discussion of expectations.","why":"A changed plan needs agreement and communication.","correct":true,"id":"A"},{"text":"Ignore stakeholder feedback because the new direction is urgent.","why":"Urgency does not remove the need to align expectations.","correct":false,"id":"B"},{"text":"Describe only management’s decision and omit how you adapted.","why":"Your own flexible response needs to be visible.","correct":false,"id":"C"},{"text":"Claim both original and revised scope were fully delivered without checking exclusions.","why":"The account should state actual trade-offs.","correct":false,"id":"D"},{"text":"Keep all changes undocumented so the team can move faster.","why":"That can create conflicting expectations.","correct":false,"id":"E"},{"text":"Explain how the scope, priorities or responsibilities changed and which needs remained important.","why":"The context of the pivot should be clear.","correct":true,"id":"F"},{"text":"Discuss a minor temporary file error as the only evidence of a wider organisational pivot.","why":"That does not establish the broader B7 context.","correct":false,"id":"G"},{"text":"Explain your personal adjustments and how feedback affected the delivered outcome.","why":"Flexibility should be demonstrated through actual actions.","correct":true,"id":"H"}],"answer":"Explain how the scope, priorities or responsibilities changed and which needs remained important. Describe the revised approach, trade-offs and discussion of expectations. Explain your personal adjustments and how feedback affected the delivered outcome.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."}}]}],"dataSha256":"7e2d226cbc4591f5a8cedc84b9e8491bb8c5ec112d95180d88cfa43ac7c3d066"};
